/* Darsi — konten BAHASA INDONESIA (terjemahan dari fr.js, struktur identik).
   Sumber: 'q:S:V' = ayat, 'h:nama' = hadis, 'f:nama' = catatan di bawah. Konten perlu ditinjau oleh orang yang kompeten. */
'use strict';
CONTENU.id={
lecons:{
/* ===================== RAMADAN & PUASA ===================== */
'r-bienvenue':{titre:"Bulan Ramadan",
 texte:["Ramadan adalah bulan ke-9 dalam kalender Islam, yang disebut kalender Hijriah. Kalender ini berdasarkan peredaran bulan: setiap bulan dimulai dengan munculnya hilal, yaitu bulan sabit baru.",
  "Satu tahun lunar berjumlah sekitar 354 hari. Karena itu, Ramadan maju sekitar sepuluh hari setiap tahun dalam kalender Masehi kita.",
  "Pada bulan inilah wahyu Al-Qur'an mulai turun. Puasa Ramadan diwajibkan pada tahun ke-2 Hijriah."],
 retenir:"Ramadan adalah bulan lunar ke-9, bulan Al-Qur'an dan bulan puasa.",
 sources:['q:2:185','h:croissant'],
 quiz:[
  {q:"Dalam kalender Islam (Hijriah), bulan Ramadan berada di urutan ke berapa?",c:["Bulan ke-9","Bulan ke-1","Bulan ke-12","Bulan ke-7"],b:0,e:"Ramadan adalah bulan ke-9. Bulan pertama tahun Hijriah adalah Muharram.",s:['f:mois']},
  {q:"Kalender Islam (Hijriah) didasarkan pada benda langit apa?",c:["Bulan","Matahari","Bintang-bintang","Tidak pada benda langit apa pun"],b:0,e:"Setiap bulan dimulai dengan munculnya hilal, bulan sabit baru.",s:['q:2:189','h:croissant']},
  {q:"Mengapa tanggal Ramadan maju sekitar 11 hari setiap tahun?",c:["Karena tahun lunar lebih pendek daripada tahun matahari","Karena para ulama menggesernya setiap tahun","Karena tahun Hijriah terdiri dari 13 bulan","Karena kita mengikuti kalender matahari Persia"],b:0,e:"Tahun lunar berjumlah sekitar 354 hari, yaitu sekitar 11 hari lebih sedikit daripada tahun matahari.",s:['q:9:36']},
  {q:"Peristiwa besar apa yang dimulai pada bulan Ramadan?",c:["Turunnya wahyu Al-Qur'an","Pembangunan Kakbah","Hijrah ke Madinah","Perang Uhud"],b:0,e:"Al-Qur'an mulai diturunkan pada bulan Ramadan.",s:['q:2:185']},
  {q:"Berapa jumlah bulan dalam satu tahun Islam (Hijriah)?",c:["12","10","13","11"],b:0,e:"Tahun Hijriah terdiri dari 12 bulan lunar.",s:['q:9:36']},
  {q:"Menurut hadis, dengan tanda apa puasa Ramadan dimulai?",c:["Ketika hilal (bulan sabit baru) terlihat","Ketika bulan purnama terlihat","Setiap tanggal 15 Syakban","Setelah Jumat pertama sesudah Syakban"],b:0,e:"“Berpuasalah kalian ketika melihatnya”: yang dimaksud adalah hilal.",s:['h:croissant']},
  {q:"Apa nama bulan sesudah Ramadan, yang hari pertamanya adalah Idulfitri?",c:["Syawal","Syakban","Rajab","Muharram"],b:0,e:"Tanggal 1 Syawal adalah hari raya Idulfitri.",s:['f:mois']},
  {q:"Bulan apa dalam kalender Islam yang tepat mendahului Ramadan?",c:["Syakban","Syawal","Zulhijah","Safar"],b:0,e:"Syakban adalah bulan ke-8, tepat sebelum Ramadan.",s:['f:mois']},
  {q:"Pada tahun Hijriah ke berapa puasa Ramadan menjadi wajib?",c:["Tahun ke-2","Tahun ke-1","Tahun ke-10","Tahun ke-8"],b:0,e:"Puasa Ramadan diwajibkan di Madinah, pada tahun ke-2 Hijriah.",s:['f:jeune2']},
  {q:"Berapa hari lamanya bulan Ramadan?",c:["29 atau 30 hari","Selalu 30 hari","28 hari","31 hari"],b:0,e:"Satu bulan lunar berlangsung 29 atau 30 hari, tergantung munculnya hilal berikutnya.",s:['h:croissant']}
 ]},
'r-jeuner':{titre:"Siapa yang wajib berpuasa?",
 texte:["Puasa Ramadan wajib bagi muslim yang sudah balig, berakal sehat, dan mampu berpuasa.",
  "Orang sakit dan musafir boleh tidak berpuasa, lalu menggantinya di hari lain. Perempuan yang sedang haid tidak berpuasa dan menggantinya kemudian.",
  "Orang yang tidak akan pernah mampu berpuasa, seperti orang yang sangat tua, memberi makan satu orang miskin untuk setiap hari yang ditinggalkan: inilah fidyah."],
 retenir:"Ada banyak keringanan: Allah menghendaki kemudahan bagi kita.",
 sources:['q:2:184','q:2:185'],
 quiz:[
  {q:"Selama Ramadan, apa yang harus dilakukan musafir yang tidak berpuasa pada beberapa hari?",c:["Mengganti hari-hari itu nanti","Tidak perlu melakukan apa-apa","Membayar denda","Berpuasa dua kali lipat"],b:0,e:"Ia mengganti puasa sebanyak hari yang ditinggalkan setelah Ramadan.",s:['q:2:184']},
  {q:"Apa nama tebusan berupa memberi makan satu orang miskin untuk setiap hari puasa yang ditinggalkan?",c:["Fidyah","Sedekah","Zakat fitrah","Kafarat"],b:0,e:"Fidyah terutama berlaku bagi orang yang tidak akan pernah bisa mengganti puasanya, seperti orang yang sangat tua.",s:['q:2:184']},
  {q:"Apakah puasa Ramadan wajib bagi anak yang belum balig?",c:["Tidak, tetapi ia boleh dibiasakan","Ya, sejak usia 7 tahun","Ya, tetapi hanya pada hari Jumat","Hanya pada sepuluh hari terakhir"],b:0,e:"Tidak wajib. Namun para sahabat membiasakan anak-anak mereka berpuasa, misalnya pada hari Asyura.",s:['h:enfants']},
  {q:"Selama Ramadan, apa yang dilakukan perempuan yang sedang haid?",c:["Ia tidak berpuasa dan mengganti hari-harinya kemudian","Ia tetap berpuasa","Ia tidak pernah menggantinya","Ia berpuasa setengah hari"],b:0,e:"Ia tidak berpuasa, lalu mengganti hari yang ditinggalkan setelah Ramadan.",s:['h:regles']},
  {q:"Apakah orang sakit yang tidak berpuasa di bulan Ramadan harus mengganti hari-hari yang ditinggalkan?",c:["Ya, ketika ia sudah mampu","Tidak, sama sekali tidak","Ya, tetapi dua kali lipat","Tidak, ia selalu membayar denda"],b:0,e:"Ia mengganti sejumlah hari yang sama ketika ia sudah mampu.",s:['q:2:184']},
  {q:"Apakah perempuan yang haid harus mengganti salat yang tidak ia kerjakan selama masa itu?",c:["Tidak, ia hanya mengganti puasa","Ya, semua salat","Ya, setengah dari salatnya","Hanya salat Jumat"],b:0,e:"Ia mengganti puasa, tetapi tidak mengganti salat.",s:['h:regles']},
  {q:"Menurut ayat tentang puasa, apa yang Allah kehendaki bagi orang-orang beriman?",c:["Kemudahan","Kesulitan","Kelelahan","Kekayaan"],b:0,e:"“Allah menghendaki kemudahan bagimu, dan tidak menghendaki kesukaran bagimu.”",s:['q:2:185']},
  {q:"Orang yang sangat tua dan tidak akan pernah mampu berpuasa lagi: apa yang ia lakukan?",c:["Ia memberi makan satu orang miskin untuk setiap hari","Ia tetap berpuasa","Ia tidak perlu melakukan apa-apa","Ia mengganti setelah Ramadan berikutnya"],b:0,e:"Itulah fidyah: satu kali makan untuk satu orang miskin per hari yang tidak dipuasai.",s:['q:2:184']},
  {q:"Bagi siapa puasa Ramadan diwajibkan?",c:["Muslim yang balig, berakal sehat, dan mampu berpuasa","Semua anak-anak","Hanya laki-laki","Hanya mereka yang sudah berhaji"],b:0,e:"Inilah syarat-syarat yang ditetapkan para ulama.",s:['f:conditions']},
  {q:"Menurut Al-Qur'an, apakah puasa sudah diwajibkan sebelum umat Islam?",c:["Ya, atas orang-orang sebelum mereka","Tidak, tidak pernah","Hanya atas penduduk Mekah","Hanya atas kaum Nabi Nuh"],b:0,e:"“Diwajibkan atas kamu berpuasa sebagaimana diwajibkan atas orang-orang sebelum kamu.”",s:['q:2:183']}
 ]},
'r-rompt':{titre:"Hal-hal yang membatalkan puasa",
 texte:["Puasa dimulai saat fajar, ketika waktu salat Subuh tiba, dan berakhir saat matahari terbenam, ketika waktu salat Magrib tiba.",
  "Makan, minum, atau berhubungan suami istri dengan sengaja pada siang hari membatalkan puasa.",
  "Orang yang makan atau minum karena lupa tetap melanjutkan puasanya: puasanya tetap sah."],
 retenir:"Makan atau minum karena lupa tidak membatalkan puasa.",
 sources:['q:2:187','h:oubli'],
 quiz:[
  {q:"Kapan puasa Ramadan dimulai dalam sehari?",c:["Saat fajar (Subuh)","Tengah malam","Saat matahari terbit","Tengah hari"],b:0,e:"Puasa dimulai saat fajar, ketika benang putih dapat dibedakan dari benang hitam.",s:['q:2:187']},
  {q:"Kapan kita berbuka puasa Ramadan?",c:["Saat matahari terbenam (Magrib)","Saat malam sudah gelap (Isya)","Pukul 16.00","Tengah malam"],b:0,e:"Kita berbuka begitu matahari terbenam.",s:['h:coucher']},
  {q:"Seseorang yang berpuasa minum air karena lupa bahwa ia sedang berpuasa. Bagaimana puasanya?",c:["Tetap sah","Batal","Ia harus menggantinya dua kali","Tergantung banyaknya"],b:0,e:"Ia menyempurnakan puasanya: Allah-lah yang memberinya makan dan minum.",s:['h:oubli']},
  {q:"Apa yang terjadi jika orang yang berpuasa makan dengan sengaja di siang hari Ramadan?",c:["Puasanya batal","Tidak ada yang berubah","Boleh jika ia berada di masjid","Boleh setelah salat Zuhur"],b:0,e:"Makan dengan sengaja pada siang hari membatalkan puasa.",s:['q:2:187']},
  {q:"Menurut Al-Qur'an, sampai kapan kita boleh makan dan minum pada malam-malam Ramadan?",c:["Sampai benang putih fajar dapat dibedakan dari benang hitam malam","Sampai tengah malam","Sampai matahari terbit","Sampai salat Isya"],b:0,e:"Inilah perumpamaan dalam ayat 187 surah Al-Baqarah.",s:['q:2:187']},
  {q:"Dalam ayat tentang puasa, apa yang dimaksud dengan “benang putih”?",c:["Cahaya fajar","Benang wol sungguhan","Bulan sabit","Bintang pertama di sore hari"],b:0,e:"Benang putih adalah terangnya fajar, benang hitam adalah gelapnya malam.",s:['q:2:187']},
  {q:"Selama Ramadan, apakah boleh makan dan minum pada malam hari, setelah matahari terbenam?",c:["Ya, sampai fajar","Tidak, sama sekali tidak selama sebulan penuh","Hanya air","Hanya setelah salat tarawih"],b:0,e:"Puasa hanya berlaku pada siang hari, dari fajar sampai matahari terbenam.",s:['q:2:187']},
  {q:"Menurut hadis, siapa yang “memberi makan dan minum” kepada orang yang makan atau minum karena lupa saat berpuasa?",c:["Allah","Keluarganya","Seorang malaikat","Tidak ada siapa pun"],b:0,e:"Puasanya tetap sah: Allah-lah yang memberinya makan dan minum.",s:['h:oubli']},
  {q:"Pada siang hari Ramadan, apakah hubungan suami istri diperbolehkan?",c:["Tidak, karena membatalkan puasa","Ya, kapan saja","Ya, pada sore hari","Hanya pada hari Asyura"],b:0,e:"Ayat 187 membolehkannya pada malam-malam Ramadan; pada siang hari, hal itu membatalkan puasa.",s:['q:2:187']},
  {q:"Salat apa yang menandai berakhirnya hari puasa?",c:["Salat Magrib","Salat Subuh","Salat Zuhur","Salat Isya"],b:0,e:"Magrib adalah salat saat matahari terbenam, waktu berbuka puasa.",s:['h:coucher']}
 ]},
'r-suhur':{titre:"Sahur dan berbuka",
 texte:["Sahur adalah makan sebelum fajar. Nabi ﷺ menganjurkannya, karena di dalamnya ada keberkahan.",
  "Iftar adalah berbuka puasa saat matahari terbenam. Dianjurkan untuk tidak menundanya.",
  "Sunahnya adalah berbuka dengan kurma segar, jika tidak ada dengan kurma kering, dan jika tidak ada juga dengan beberapa teguk air."],
 retenir:"Sahur sebelum fajar. Berbuka begitu matahari terbenam, dengan kurma.",
 sources:['h:suhur','h:dattes'],
 quiz:[
  {q:"Apa nama makanan yang disantap sebelum fajar selama Ramadan?",c:["Sahur","Iftar","Walimah","Akikah"],b:0,e:"Sahur adalah makan di akhir malam, sebelum Subuh.",s:['h:suhur']},
  {q:"Menurut hadis, apa yang terkandung dalam makan sahur?",c:["Keberkahan","Sebuah kewajiban","Tidak ada yang istimewa","Sebuah ujian"],b:0,e:"“Bersahurlah kalian, karena dalam sahur itu ada keberkahan.”",s:['h:suhur']},
  {q:"Dengan apa Nabi ﷺ lebih suka berbuka puasa?",c:["Kurma","Susu unta","Sup harira","Roti"],b:0,e:"Kurma segar, jika tidak ada kurma kering, dan jika tidak ada beberapa teguk air.",s:['h:dattes']},
  {q:"Apakah berbuka puasa (iftar) perlu ditunda setelah matahari terbenam?",c:["Tidak, justru dianjurkan untuk menyegerakannya","Ya, satu jam","Ya, sampai Isya","Itu tidak penting sama sekali"],b:0,e:"Dianjurkan berbuka begitu matahari terbenam.",s:['h:hater']},
  {q:"Apa nama makanan untuk berbuka puasa saat matahari terbenam?",c:["Iftar","Sahur","Mandi wajib (gusl)","Zikir"],b:0,e:"Iftar adalah berbuka puasa.",s:['h:hater']},
  {q:"Jika tidak ada kurma, dengan apa Nabi ﷺ berbuka puasa?",c:["Beberapa teguk air","Madu","Susu kambing","Buah tin"],b:0,e:"Kurma segar, jika tidak ada kurma kering, dan jika tidak ada beberapa teguk air.",s:['h:dattes']},
  {q:"Apakah Nabi ﷺ berbuka puasa sebelum atau sesudah salat Magrib?",c:["Sebelum salat","Sesudah salat","Keesokan harinya","Sesudah salat Isya"],b:0,e:"Beliau berbuka sebelum salat, dengan beberapa butir kurma.",s:['h:dattes']},
  {q:"Menurut hadis, selama orang-orang menyegerakan berbuka puasa, mereka tetap…",c:["Dalam kebaikan","Dalam keraguan","Dalam bahaya","Tanpa pahala"],b:0,e:"“Manusia senantiasa dalam kebaikan selama mereka menyegerakan berbuka.”",s:['h:hater']},
  {q:"Apakah sahur wajib agar puasa sah?",c:["Tidak, tetapi sangat dianjurkan","Ya, jika tidak puasanya batal","Ya, hanya pada hari pertama","Sahur itu dilarang"],b:0,e:"Sahur adalah sunah: Nabi ﷺ menganjurkannya karena keberkahannya.",s:['h:suhur']},
  {q:"Jenis kurma apa yang lebih disukai Nabi ﷺ untuk berbuka puasa?",c:["Kurma segar (ruthab)","Kurma kering (tamr)","Buah tin kering","Kismis"],b:0,e:"Beliau memulai dengan kurma segar; jika tidak ada, dengan kurma kering.",s:['h:dattes']}
 ]},
'r-merites':{titre:"Keutamaan puasa",
 texte:["Allah mewajibkan puasa agar orang beriman mencapai takwa: kesadaran akan Allah dalam setiap perbuatan.",
  "Nabi ﷺ menjanjikan ampunan atas dosa-dosa yang telah lalu bagi orang yang berpuasa Ramadan karena iman dan mengharap pahala dari Allah.",
  "Di akhir bulan, setiap muslim menunaikan zakat fitrah sebelum salat Id. Zakat ini menyucikan orang yang berpuasa dan memberi makan orang-orang miskin."],
 retenir:"Puasa membawa kepada takwa. Zakat fitrah ditunaikan sebelum salat Id.",
 sources:['q:2:183','h:pardon','h:fitr'],
 quiz:[
  {q:"Menurut Al-Qur'an, untuk tujuan apa Allah mewajibkan puasa?",c:["Agar mencapai takwa","Hanya untuk menyucikan tubuh","Untuk memperingati Hijrah","Untuk menggantikan zakat"],b:0,e:"Ayat yang mewajibkan puasa diakhiri dengan harapan agar kita bertakwa.",s:['q:2:183']},
  {q:"Menurut hadis, apa yang didapat orang yang berpuasa Ramadan karena iman dan mengharap pahala dari Allah?",c:["Dosa-dosanya yang telah lalu diampuni","Ia tidak perlu salat lagi","Ia dibebaskan dari zakat","Tidak ada yang istimewa"],b:0,e:"Dosa-dosanya yang telah lalu diampuni.",s:['h:pardon']},
  {q:"Kapan zakat fitrah harus ditunaikan?",c:["Sebelum salat Idulfitri","Sebulan setelah Ramadan","Hanya di awal Ramadan","Kapan saja sepanjang tahun"],b:0,e:"Nabi ﷺ memerintahkan agar zakat fitrah ditunaikan sebelum orang-orang keluar untuk salat Id.",s:['h:fitr']},
  {q:"Apa arti kata “takwa”?",c:["Kesalehan, kesadaran akan Allah","Kesabaran (sabar)","Rasa syukur (syukur)","Pertobatan (taubat)"],b:0,e:"Takwa adalah rasa takut yang disertai pengagungan kepada Allah, yang mendorong kepada kebaikan.",s:['q:2:183']},
  {q:"Siapa yang wajib menunaikan zakat fitrah?",c:["Setiap muslim, kecil maupun besar, laki-laki maupun perempuan","Hanya orang kaya","Hanya laki-laki","Hanya mereka yang berpuasa sebulan penuh"],b:0,e:"Hadis mewajibkannya atas setiap muslim; kepala keluarga menunaikannya untuk anggota keluarganya.",s:['h:fitr']},
  {q:"Berapa takaran makanan yang ditetapkan hadis untuk zakat fitrah?",c:["Satu sha'","Satu mitsqal emas","Satu mud gandum","Satu dirham perak"],b:0,e:"Satu sha' adalah takaran sekitar empat kali cakupan dua telapak tangan.",s:['h:fitr']},
  {q:"Makanan apa yang disebutkan dalam hadis zakat fitrah yang diriwayatkan Ibnu Umar?",c:["Kurma atau jelai","Beras atau couscous","Daging atau ikan","Susu atau madu"],b:0,e:"Satu sha' kurma atau satu sha' jelai.",s:['h:fitr']},
  {q:"Menurut hadis, dengan syarat apa puasa Ramadan menghapus dosa-dosa yang telah lalu?",c:["Dengan iman dan mengharap pahala dari Allah","Dengan berpuasa sambil diam","Dengan berpuasa 40 hari","Tanpa syarat apa pun"],b:0,e:"Kita harus berpuasa karena iman dan mengharap pahala dari Allah.",s:['h:pardon']},
  {q:"Apa tujuan zakat fitrah menurut hadis Ibnu Abbas?",c:["Menyucikan orang yang berpuasa dan memberi makan orang miskin","Membiayai pembangunan masjid","Menggantikan puasa orang sakit","Memberi upah imam tarawih"],b:0,e:"Zakat fitrah menyucikan orang yang berpuasa dari perkataan sia-sia dan memberi makan orang miskin.",s:['h:fitr_but']},
  {q:"Dengan seruan apa ayat yang mewajibkan puasa Ramadan dimulai?",c:["“Wahai orang-orang yang beriman!”","“Wahai manusia!”","“Wahai Nabi!”","“Wahai anak cucu Adam!”"],b:0,e:"Ayat 183 surah Al-Baqarah dimulai dengan “Wahai orang-orang yang beriman!”.",s:['q:2:183']}
 ]},
'r-nuits':{titre:"Malam-malam Ramadan",
 texte:["Malam-malam Ramadan adalah kesempatan untuk memperbanyak salat. Salat malamnya disebut tarawih. Nabi ﷺ menjanjikan ampunan bagi orang yang menghidupkan malam-malam Ramadan dengan salat karena iman dan mengharap pahala.",
  "Pada sepuluh malam terakhir, beliau semakin bersungguh-sungguh: beliau menghidupkan malam dengan salat dan membangunkan keluarganya.",
  "Beliau juga beriktikaf, yaitu berdiam diri di masjid untuk beribadah selama sepuluh hari terakhir, dan hal itu beliau lakukan hingga akhir hayatnya."],
 retenir:"Tarawih, sepuluh malam terakhir, iktikaf: malam-malam Ramadan dihidupkan dengan salat.",
 sources:['h:qiyam','h:dixnuits','h:itikaf'],
 quiz:[
  {q:"Apa nama salat malam yang dikerjakan selama Ramadan?",c:["Tarawih","Salat Duha","Salat istikharah","Salat jenazah"],b:0,e:"Tarawih adalah salat malam di bulan Ramadan.",s:['h:qiyam']},
  {q:"Menurut hadis, apa yang didapat orang yang menghidupkan malam-malam Ramadan dengan salat karena iman dan mengharap pahala?",c:["Dosa-dosanya yang telah lalu diampuni","Tempat di saf pertama masjid","Ia tidak perlu berpuasa lagi","Tidak ada yang istimewa"],b:0,e:"Dosa-dosanya yang telah lalu diampuni.",s:['h:qiyam']},
  {q:"Apa itu iktikaf?",c:["Berdiam diri di masjid untuk beribadah","Perjalanan ke Mekah","Puasa Asyura","Sebuah sedekah"],b:0,e:"Seseorang tinggal di masjid untuk mencurahkan diri dalam ibadah.",s:['h:itikaf']},
  {q:"Pada periode mana dari Ramadan Nabi ﷺ beriktikaf?",c:["Sepuluh hari terakhir","Sepuluh hari pertama","Hanya hari pertama","Setelah Idulfitri"],b:0,e:"Beliau beriktikaf pada sepuluh hari terakhir Ramadan.",s:['h:itikaf']},
  {q:"Apa yang dilakukan Nabi ﷺ pada sepuluh malam terakhir Ramadan?",c:["Beliau menghidupkan malam dengan salat dan membangunkan keluarganya","Beliau bepergian","Beliau tidur lebih awal","Beliau berhenti berpuasa"],b:0,e:"Beliau semakin bersungguh-sungguh dalam ibadah.",s:['h:dixnuits']},
  {q:"Apakah Nabi ﷺ beriktikaf hingga akhir hayatnya?",c:["Ya, sampai beliau wafat","Tidak, hanya sekali","Tidak, tidak pernah","Hanya di Mekah"],b:0,e:"Aisyah meriwayatkan bahwa beliau melakukannya sampai Allah memanggilnya kembali kepada-Nya.",s:['h:itikaf']},
  {q:"Di mana iktikaf dilakukan?",c:["Di masjid","Di rumah","Di Gua Hira","Di pemakaman"],b:0,e:"Al-Qur'an menyebut orang-orang yang sedang beriktikaf di masjid.",s:['q:2:187']},
  {q:"Malam yang sangat penting apa yang ada di antara sepuluh malam terakhir Ramadan?",c:["Lailatul Qadar, Malam Kemuliaan","Malam Hijrah","Malam Iduladha","Malam Maulid"],b:0,e:"Malam itu dicari pada malam-malam ganjil di sepuluh malam terakhir.",s:['h:qadr']},
  {q:"Apakah salat tarawih wajib?",c:["Tidak, salat ini sunah yang sangat dianjurkan","Ya, seperti salat lima waktu","Ya, tetapi hanya di masjid","Salat ini dilarang"],b:0,e:"Nabi ﷺ mengerjakannya berjamaah beberapa malam, lalu berhenti karena khawatir salat itu menjadi wajib.",s:['h:tarawih']},
  {q:"Mengapa Nabi ﷺ berhenti memimpin tarawih berjamaah setelah beberapa malam?",c:["Karena khawatir salat itu menjadi wajib","Karena beliau sakit","Karena masjidnya terlalu kecil","Karena Ramadan sudah selesai"],b:0,e:"Beliau khawatir salat itu diwajibkan atas umatnya.",s:['h:tarawih']}
 ]},
'r-qadr':{titre:"Lailatul Qadar, Malam Kemuliaan",
 texte:["Lailatul Qadar, Malam Kemuliaan, adalah malam ketika wahyu Al-Qur'an mulai turun.",
  "Allah berfirman bahwa malam itu “lebih baik daripada seribu bulan”. Para malaikat turun pada malam itu, dan malam itu penuh kesejahteraan sampai terbit fajar. Satu surah utuh dikhususkan untuknya: surah Al-Qadr (97).",
  "Malam itu dicari pada sepuluh malam terakhir Ramadan, terutama malam-malam ganjil, dengan memperbanyak salat dan doa."],
 retenir:"Lebih baik daripada seribu bulan. Carilah pada malam-malam ganjil di sepuluh malam terakhir.",
 sources:['q:97:1','q:97:3','h:qadr'],
 quiz:[
  {q:"Menurut Al-Qur'an, Lailatul Qadar (Malam Kemuliaan) lebih baik daripada berapa lama waktu?",c:["Seribu bulan","Seratus hari","Satu tahun","Sepuluh malam"],b:0,e:"Malam itu lebih baik daripada seribu bulan, yaitu lebih dari 83 tahun.",s:['q:97:3']},
  {q:"Surah Al-Qur'an apa yang dikhususkan untuk Lailatul Qadar (Malam Kemuliaan)?",c:["Al-Qadr","Al-Fatihah","Al-Ikhlas","Yasin"],b:0,e:"Surah ke-97, Al-Qadr, dinamai dengan nama malam ini.",s:['q:97:1']},
  {q:"Pada malam-malam Ramadan yang mana Lailatul Qadar (Malam Kemuliaan) terutama dicari?",c:["Malam-malam ganjil di sepuluh malam terakhir","Sepuluh malam pertama","Malam pertama","Malam Idulfitri"],b:0,e:"Malam-malam ganjil di sepuluh malam terakhir: 21, 23, 25, 27, dan 29.",s:['h:qadr']},
  {q:"Peristiwa apa yang terjadi pada Lailatul Qadar (Malam Kemuliaan)?",c:["Permulaan turunnya wahyu Al-Qur'an","Hijrah ke Madinah","Kelahiran Nabi ﷺ","Haji yang pertama"],b:0,e:"Wahyu Al-Qur'an mulai turun pada malam itu.",s:['q:97:1']},
  {q:"Menurut surah Al-Qadr, siapa yang turun pada Malam Kemuliaan?",c:["Para malaikat dan Ruh (Jibril)","Para nabi","Para jin","Tidak ada siapa pun"],b:0,e:"Para malaikat dan Ruh turun pada malam itu dengan izin Tuhan mereka.",s:['q:97:4']},
  {q:"Menurut surah Al-Qadr, sampai kapan Malam Kemuliaan itu penuh kesejahteraan?",c:["Sampai terbit fajar","Sampai tengah malam","Sampai akhir Ramadan","Sampai Idulfitri"],b:0,e:"“Malam itu penuh kesejahteraan sampai terbit fajar.”",s:['q:97:5']},
  {q:"Berapa jumlah ayat surah Al-Qadr?",c:["5","7","3","10"],b:0,e:"Surah Al-Qadr terdiri dari 5 ayat.",s:['q:97:5']},
  {q:"Seribu bulan kira-kira sama dengan berapa tahun?",c:["Lebih dari 83 tahun","10 tahun","40 tahun","1.000 tahun"],b:0,e:"1.000 bulan ÷ 12 ≈ 83 tahun 4 bulan: lebih dari seumur hidup.",s:['q:97:3']},
  {q:"Manakah malam-malam ganjil di sepuluh malam terakhir Ramadan?",c:["21, 23, 25, 27, dan 29","20, 22, 24, 26, dan 28","1, 3, 5, 7, dan 9","11, 13, 15, 17, dan 19"],b:0,e:"Inilah malam-malam yang dianjurkan untuk mencari Lailatul Qadar.",s:['h:qadr']},
  {q:"Doa apa yang diajarkan Nabi ﷺ kepada Aisyah untuk Malam Kemuliaan?",c:["“Allâhumma innaka ʿafuwwun tuḥibbu l-ʿafwa faʿfu ʿannî”","“Bismi Llâh”","“Allâhu akbar”","“Subḥâna Llâh”"],b:0,e:"“Ya Allah, Engkau Maha Pemaaf, Engkau menyukai pemaafan, maka maafkanlah aku.”",s:['h:afw']}
 ]},
'r-aid':{titre:"Idulfitri",
 texte:["Idulfitri adalah hari raya berbuka (berakhirnya puasa). Hari raya ini jatuh pada tanggal 1 Syawal, tepat setelah Ramadan.",
  "Sebelum berangkat untuk salat Id, Nabi ﷺ makan beberapa butir kurma dalam jumlah ganjil. Zakat fitrah harus ditunaikan sebelum salat ini.",
  "Setelah Idulfitri, dianjurkan berpuasa enam hari di bulan Syawal: bersama Ramadan, pahalanya seperti berpuasa setahun penuh."],
 retenir:"1 Syawal: Idulfitri. Kurma sebelum salat, lalu enam hari puasa Syawal.",
 sources:['h:aid_dattes','h:shawwal','q:2:185'],
 quiz:[
  {q:"Pada hari apa Idulfitri jatuh?",c:["Tanggal 1 Syawal","Tanggal 27 Ramadan","Tanggal 10 Zulhijah","Tanggal 1 Muharram"],b:0,e:"Idulfitri datang tepat setelah bulan Ramadan.",s:['f:mois']},
  {q:"Apa arti “Idulfitri”?",c:["Hari raya berbuka (berakhirnya puasa)","Hari raya kurban","Hari raya Hijrah","Hari raya kelahiran Nabi ﷺ"],b:0,e:"Fitri (fithr) berarti berbuka, yaitu berakhirnya puasa.",s:['f:aid']},
  {q:"Apa yang dimakan Nabi ﷺ sebelum berangkat untuk salat Idulfitri?",c:["Beberapa butir kurma","Buah tin","Daging","Tidak ada, beliau berpuasa"],b:0,e:"Beliau tidak berangkat pada hari Idulfitri sebelum makan beberapa butir kurma.",s:['h:aid_dattes']},
  {q:"Dalam jumlah berapa Nabi ﷺ makan kurma pada pagi hari Idulfitri?",c:["Dalam jumlah ganjil","Selalu dua","Selalu tujuh","Dalam jumlah genap"],b:0,e:"Anas meriwayatkan bahwa beliau memakannya dalam jumlah ganjil.",s:['h:aid_dattes']},
  {q:"Berapa hari raya (Id) dalam Islam setiap tahun?",c:["2","1","3","5"],b:0,e:"Idulfitri dan Iduladha.",s:['f:aid']},
  {q:"Menurut hadis, berapa hari di bulan Syawal yang dianjurkan untuk berpuasa setelah Ramadan?",c:["6","3","10","30"],b:0,e:"Enam hari di bulan Syawal, berturut-turut atau tidak.",s:['h:shawwal']},
  {q:"Menurut hadis, berpuasa Ramadan lalu enam hari di bulan Syawal setara dengan apa?",c:["Berpuasa setahun penuh","Berhaji","Berpuasa satu bulan tambahan","Tidak ada yang istimewa"],b:0,e:"Seakan-akan ia berpuasa setahun penuh.",s:['h:shawwal']},
  {q:"Sebelum salat apa zakat fitrah harus sudah ditunaikan?",c:["Salat Id","Salat Jumat","Salat Magrib","Tarawih"],b:0,e:"Zakat fitrah harus ditunaikan sebelum orang-orang keluar untuk salat Id.",s:['h:fitr']},
  {q:"Menurut ayat 185 surah Al-Baqarah, apa yang dilakukan orang beriman setelah menyempurnakan bilangan hari Ramadan?",c:["Mereka mengagungkan kebesaran Allah","Mereka mulai berpuasa lagi","Mereka beriktikaf","Mereka pergi berziarah ke Madinah"],b:0,e:"Ayat itu mengajak untuk mengagungkan Allah atas petunjuk yang diberikan: inilah takbir Idulfitri.",s:['q:2:185']},
  {q:"Apa hari raya besar lainnya dalam Islam, yang dirayakan pada musim haji?",c:["Iduladha","Idulfitri","Maulid","1 Muharram"],b:0,e:"Iduladha, hari raya kurban, jatuh pada tanggal 10 Zulhijah.",s:['f:aid']}
 ]},

/* ===================== RUKUN ISLAM & SALAT ===================== */
'p-piliers':{titre:"Lima rukun Islam",
 texte:["Islam dibangun di atas lima rukun, yang disebutkan dalam hadis sahih riwayat Al-Bukhari dan Muslim.",
  "Syahadat, yaitu persaksian iman. Salat, yaitu salat lima waktu setiap hari. Zakat, yaitu sedekah wajib. Haji, yaitu ziarah ke Mekah bagi yang mampu. Saum, yaitu puasa Ramadan.",
  "Kelima rukun ini adalah fondasi amalan seorang muslim sepanjang tahun."],
 retenir:"Syahadat, salat, zakat, haji, puasa Ramadan.",
 sources:['h:piliers'],
 quiz:[
  {q:"Berapa jumlah rukun Islam?",c:["5","3","4","6"],b:0,e:"Islam dibangun di atas lima rukun.",s:['h:piliers']},
  {q:"Apa sebutan puasa dalam bahasa Arab?",c:["Saum (atau siyam)","Salat","Zakat","Haji"],b:0,e:"Puasa disebut saum atau siyam; itulah kata yang dipakai dalam ayat yang mewajibkannya.",s:['q:2:183']},
  {q:"Bagi siapa ibadah haji ke Mekah diwajibkan?",c:["Bagi yang mampu, sekali seumur hidup","Bagi semua orang, setiap tahun","Hanya bagi laki-laki","Hanya selama Ramadan"],b:0,e:"Haji wajib sekali seumur hidup bagi yang mampu secara fisik dan finansial.",s:['q:3:97']},
  {q:"Berapa kali salat wajib yang dikerjakan seorang muslim setiap hari?",c:["5","3","7","2"],b:0,e:"Subuh, Zuhur, Asar, Magrib, dan Isya.",s:['h:cinq']},
  {q:"Apa rukun Islam yang pertama?",c:["Syahadat, persaksian iman","Puasa","Haji","Zakat"],b:0,e:"Syahadat disebut pertama dalam hadis.",s:['h:piliers']},
  {q:"Rukun Islam manakah yang merupakan sedekah wajib?",c:["Zakat","Salat","Saum","Syahadat"],b:0,e:"Zakat dikeluarkan setiap tahun atas harta yang mencapai batas tertentu.",s:['h:piliers']},
  {q:"Rukun Islam manakah yang dikerjakan selama bulan Ramadan?",c:["Puasa (saum)","Haji","Zakat","Syahadat"],b:0,e:"Puasa Ramadan adalah salah satu dari lima rukun Islam.",s:['h:piliers']},
  {q:"Rukun Islam manakah yang berupa perjalanan ke Mekah?",c:["Haji","Salat","Saum","Zakat"],b:0,e:"Haji adalah ziarah ke Baitullah (Rumah Suci).",s:['q:3:97']},
  {q:"Menurut hadis, berapa kali haji diwajibkan seumur hidup?",c:["Hanya sekali","Setiap tahun","Tiga kali","Tujuh kali"],b:0,e:"Nabi ﷺ menegaskan bahwa haji tidak diwajibkan setiap tahun.",s:['h:hajj_une']},
  {q:"Sahabat siapa yang meriwayatkan hadis tentang lima rukun Islam?",c:["Abdullah bin Umar","Abu Bakar","Bilal","Khalid bin Walid"],b:0,e:"Hadis ini diriwayatkan oleh Ibnu Umar.",s:['h:piliers']}
 ]},
'p-shahada':{titre:"Syahadat, persaksian iman",
 texte:["Syahadat adalah persaksian iman: “Ash-hadu an lâ ilâha illâ Llâh, wa ash-hadu anna Muḥammadan rasûlu Llâh”.",
  "Artinya: “Aku bersaksi bahwa tiada tuhan selain Allah, dan aku bersaksi bahwa Muhammad adalah utusan Allah.”",
  "Inilah rukun pertama: dengannya seseorang masuk Islam. Syahadat menegaskan keesaan Allah, yaitu tauhid, yang dirangkum dalam surah Al-Ikhlas."],
 retenir:"Lâ ilâha illâ Llâh, Muḥammadun rasûlu Llâh.",
 sources:['q:47:19','q:48:29','h:piliers'],
 quiz:[
  {q:"Rukun Islam manakah yang merupakan persaksian iman?",c:["Syahadat","Salat","Zakat","Haji"],b:0,e:"Syahadat adalah rukun yang pertama.",s:['h:piliers']},
  {q:"Apa arti “lâ ilâha illâ Llâh”?",c:["Tiada tuhan selain Allah","Allah Maha Besar","Maha Suci Allah","Dengan nama Allah"],b:0,e:"Inilah bagian pertama syahadat.",s:['q:47:19']},
  {q:"Apa arti “Muḥammadun rasûlu Llâh”?",c:["Muhammad adalah utusan Allah","Muhammad adalah malaikat","Muhammad adalah manusia pertama","Muhammad adalah seorang raja"],b:0,e:"Inilah bagian kedua syahadat.",s:['q:48:29']},
  {q:"Apa nama keyakinan akan keesaan Allah?",c:["Tauhid","Haji","Sunah","Fikih"],b:0,e:"Tauhid adalah inti keimanan seorang muslim.",s:['q:112:1']},
  {q:"Surah apa yang merangkum keesaan Allah dalam empat ayat?",c:["Al-Ikhlas","Al-Fatihah","Al-Kautsar","An-Nas"],b:0,e:"Surah ke-112, Al-Ikhlas.",s:['q:112:1']},
  {q:"Terdiri dari berapa bagian syahadat itu?",c:["Dua: keesaan Allah dan risalah Muhammad ﷺ","Hanya satu","Lima","Tujuh"],b:0,e:"Kita bersaksi atas keesaan Allah, lalu bahwa Muhammad ﷺ adalah utusan-Nya.",s:['h:piliers']},
  {q:"Menurut surah Al-Ikhlas, apakah Allah beranak atau diperanakkan?",c:["Tidak keduanya","Keduanya","Dia beranak","Dia diperanakkan"],b:0,e:"“Dia tidak beranak dan tidak pula diperanakkan.”",s:['q:112:3']},
  {q:"Apa arti “Ash-hadu” di awal syahadat?",c:["Aku bersaksi","Aku salat","Aku berpuasa","Aku memaafkan"],b:0,e:"Ash-hadu berarti “aku bersaksi, aku memberi kesaksian”.",s:['f:shahada']},
  {q:"Apa yang dilakukan seseorang untuk masuk Islam?",c:["Mengucapkan syahadat dengan keyakinan","Berpuasa sebulan","Berhaji","Belajar bahasa Arab"],b:0,e:"Syahadat yang diucapkan dengan tulus membuat seseorang masuk Islam.",s:['f:shahada']},
  {q:"Apa yang dikatakan Al-Qur'an tentang Muhammad ﷺ dalam surah Ali Imran ayat 144?",c:["Ia hanyalah seorang rasul, dan telah berlalu rasul-rasul sebelumnya","Ia kekal abadi","Ia seorang malaikat","Ia nabi yang pertama"],b:0,e:"Muhammad ﷺ adalah manusia dan seorang rasul, seperti mereka yang mendahuluinya.",s:['q:3:144']}
 ]},
'p-priere':{titre:"Salat, lima janji temu setiap hari",
 texte:["Seorang muslim salat lima kali sehari: Subuh saat fajar, Zuhur saat tengah hari, Asar pada sore hari, Magrib saat matahari terbenam, dan Isya pada malam hari.",
  "Setiap salat terdiri dari jumlah rakaat tertentu: 2 untuk Subuh, 4 untuk Zuhur, 4 untuk Asar, 3 untuk Magrib, dan 4 untuk Isya.",
  "Kita salat menghadap Kakbah di Mekah: itulah kiblat. Waktu setiap salat diumumkan dengan azan. Pada hari Jumat, salat Zuhur diganti dengan salat Jumat."],
 retenir:"Subuh 2, Zuhur 4, Asar 4, Magrib 3, Isya 4 — menghadap kiblat.",
 sources:['q:4:103','f:rakat','q:2:144'],
 quiz:[
  {q:"Berapa rakaat salat wajib Subuh?",c:["2","3","4","1"],b:0,e:"Salat Subuh terdiri dari 2 rakaat.",s:['f:rakat']},
  {q:"Berapa rakaat salat wajib Magrib?",c:["3","2","4","5"],b:0,e:"Magrib adalah satu-satunya salat wajib yang terdiri dari 3 rakaat.",s:['f:rakat']},
  {q:"Ke arah mana umat Islam menghadap saat salat?",c:["Ke Kakbah, di Mekah","Ke Yerusalem","Ke Madinah","Ke timur"],b:0,e:"Arah ini disebut kiblat.",s:['q:2:144']},
  {q:"Apa nama seruan yang mengumumkan masuknya waktu salat?",c:["Azan","Iqamah","Doa","Zikir"],b:0,e:"Azan mengumumkan masuknya waktu; iqamah mengumumkan dimulainya salat berjamaah.",s:['h:adhan']},
  {q:"Apa nama salat wajib yang dikerjakan saat fajar?",c:["Subuh","Zuhur","Asar","Isya"],b:0,e:"Subuh dikerjakan antara fajar dan terbitnya matahari.",s:['f:rakat']},
  {q:"Berapa rakaat salat wajib Zuhur?",c:["4","2","3","5"],b:0,e:"Zuhur terdiri dari 4 rakaat.",s:['f:rakat']},
  {q:"Berapa jumlah total rakaat wajib dalam salat lima waktu sehari?",c:["17","15","20","12"],b:0,e:"2 + 4 + 4 + 3 + 4 = 17 rakaat.",s:['f:rakat']},
  {q:"Menurut Al-Qur'an, bagaimana salat diwajibkan atas orang-orang beriman?",c:["Pada waktu-waktu yang telah ditentukan","Sekali seminggu","Kapan saja kita mau","Hanya selama Ramadan"],b:0,e:"“Sesungguhnya salat itu adalah kewajiban yang ditentukan waktunya atas orang-orang yang beriman.”",s:['q:4:103']},
  {q:"Salat berjamaah apa yang dikerjakan setiap Jumat sebagai pengganti Zuhur?",c:["Salat Jumat","Salat Id","Tarawih","Salat istisqa (minta hujan)"],b:0,e:"Al-Qur'an menyeru untuk bersegera mengingat Allah pada hari Jumat.",s:['q:62:9']},
  {q:"Menurut hadis, pada peristiwa apa salat lima waktu diwajibkan?",c:["Isra Mikraj (perjalanan malam)","Perang Badar","Hijrah","Penaklukan Mekah"],b:0,e:"Lima puluh salat diwajibkan, lalu dikurangi menjadi lima.",s:['h:cinq']}
 ]},
'p-ablutions':{titre:"Wudu dan Al-Fatihah",
 texte:["Sebelum salat, seorang muslim bersuci dengan air: inilah wudu. Jika tidak ada air, ia bertayamum dengan tanah yang bersih.",
  "Kita membasuh wajah, tangan, dan lengan sampai siku, mengusap kepala dengan tangan yang basah, lalu membasuh kaki sampai mata kaki.",
  "Dalam setiap rakaat salat, kita membaca surah Al-Fatihah, “Pembukaan”, surah pertama Al-Qur'an, yang terdiri dari 7 ayat."],
 retenir:"Tidak ada salat tanpa wudu, tidak ada salat tanpa Al-Fatihah.",
 sources:['q:5:6','q:1:2','h:fatiha'],
 quiz:[
  {q:"Apa nama cara bersuci dengan air sebelum salat?",c:["Wudu","Puasa","Zakat","Iktikaf"],b:0,e:"Wudu menyucikan diri sebelum salat.",s:['q:5:6']},
  {q:"Surah apa yang dibaca dalam setiap rakaat salat?",c:["Al-Fatihah","Al-Ikhlas","Al-Baqarah","Yasin"],b:0,e:"Al-Fatihah, “Pembukaan”, dibaca dalam setiap rakaat.",s:['h:fatiha']},
  {q:"Dengan kalimat apa surah Al-Fatihah dimulai?",c:["Bismi Llâhi r-Raḥmâni r-Raḥîm","Qul huwa Llâhu aḥad","Allâhu akbar","Subḥâna Llâh"],b:0,e:"“Dengan nama Allah Yang Maha Pengasih, Maha Penyayang.”",s:['q:1:1']},
  {q:"Menurut Al-Qur'an, sampai mana lengan dibasuh saat berwudu?",c:["Sampai siku","Sampai pergelangan tangan","Sampai bahu","Hanya jari-jari"],b:0,e:"Ayat 6 surah Al-Maidah menjelaskannya.",s:['q:5:6']},
  {q:"Menurut Al-Qur'an, apa yang dilakukan pada kepala saat berwudu?",c:["Mengusapnya dengan tangan yang basah","Membasuhnya seluruhnya tiga kali","Menutupnya dengan sorban","Menuangkan air ke tengkuk"],b:0,e:"Inilah mash: mengusap kepala dengan tangan yang basah.",s:['q:5:6']},
  {q:"Apa yang dilakukan jika tidak ada air untuk bersuci sebelum salat?",c:["Tayamum, dengan tanah yang bersih","Tidak salat","Menunggu sampai keesokan hari","Salat tanpa bersuci"],b:0,e:"Ayat yang sama menetapkan tayamum ketika tidak ada air.",s:['q:5:6']},
  {q:"Menurut hadis, apakah Allah menerima salat orang yang batal wudunya tanpa berwudu kembali?",c:["Tidak, sampai ia berwudu kembali","Ya, selalu","Ya, pada hari Jumat","Hanya salat Subuh"],b:0,e:"Salat hanya diterima setelah ia berwudu kembali.",s:['h:wudu']},
  {q:"Berapa jumlah ayat surah Al-Fatihah?",c:["7","5","10","3"],b:0,e:"Surah ini disebut “tujuh ayat yang diulang-ulang”.",s:['q:15:87']},
  {q:"Apa arti “Al-ḥamdu li-Llâhi rabbi l-ʿâlamîn”?",c:["Segala puji bagi Allah, Tuhan seluruh alam","Allah Maha Besar","Tiada tuhan selain Allah","Aku berlindung kepada Allah"],b:0,e:"Inilah ayat ke-2 Al-Fatihah.",s:['q:1:2']},
  {q:"Menurut hadis, bagaimana salat orang yang tidak membaca Al-Fatihah?",c:["Tidak sah","Dihitung dua kali lipat","Sah","Dihitung setengah"],b:0,e:"“Tidak ada salat bagi orang yang tidak membaca Al-Fatihah.”",s:['h:fatiha']}
 ]},
'p-zakat':{titre:"Zakat, sedekah wajib",
 texte:["Zakat adalah sedekah wajib, salah satu dari lima rukun Islam. Namanya mengandung makna penyucian dan pertumbuhan: zakat menyucikan harta dan membantu orang-orang yang paling membutuhkan.",
  "Zakat wajib atas orang yang tabungannya mencapai batas minimum (nisab) dan tetap dimilikinya selama satu tahun lunar penuh. Untuk uang, besarnya 2,5%.",
  "Al-Qur'an menyebutkan delapan golongan penerima, di antaranya fakir dan miskin. Adapun sedekah adalah pemberian sukarela, yang bisa dilakukan kapan saja."],
 retenir:"Zakat: 2,5% dari tabungan yang mencapai nisab selama satu tahun lunar.",
 sources:['q:9:60','q:9:103','f:zakat'],
 quiz:[
  {q:"Rukun Islam manakah yang merupakan sedekah wajib?",c:["Zakat","Sedekah","Haji","Saum"],b:0,e:"Zakat itu wajib; sedekah bersifat sukarela.",s:['h:piliers']},
  {q:"Berapa kadar zakat atas uang tabungan?",c:["2,5%","10%","20%","5%"],b:0,e:"Yaitu seperempat puluh dari tabungan.",s:['f:zakat']},
  {q:"Apa nama batas minimum kekayaan yang membuat zakat menjadi wajib?",c:["Nisab","Sha'","Fidyah","Haul"],b:0,e:"Di bawah nisab, zakat tidak wajib.",s:['f:zakat']},
  {q:"Berapa lama tabungan harus dimiliki agar zakat menjadi wajib?",c:["Satu tahun lunar","Satu bulan","Sepuluh tahun","Hanya selama bulan Ramadan"],b:0,e:"Inilah haul: satu tahun lunar penuh.",s:['f:zakat']},
  {q:"Menurut Al-Qur'an, berapa golongan orang yang berhak menerima zakat?",c:["8","5","3","12"],b:0,e:"Ayat 60 surah At-Taubah menyebutkan delapan golongan.",s:['q:9:60']},
  {q:"Siapa saja yang termasuk penerima zakat yang disebutkan dalam Al-Qur'an?",c:["Fakir dan miskin","Orang-orang terkaya","Para pedagang","Para imam masjid"],b:0,e:"Fakir dan miskin disebutkan paling awal.",s:['q:9:60']},
  {q:"Apa perbedaan antara zakat dan sedekah?",c:["Zakat wajib, sedekah sukarela","Tidak ada perbedaan","Sedekah wajib","Zakat dilarang"],b:0,e:"Sedekah bisa diberikan kapan saja dan dalam jumlah berapa pun.",s:['f:zakat']},
  {q:"Dalam Al-Qur'an, zakat sangat sering disebut bersama amalan apa?",c:["Salat","Puasa","Haji","Wudu"],b:0,e:"“Dan dirikanlah salat dan tunaikanlah zakat”: ungkapan ini berulang kali muncul.",s:['q:2:43']},
  {q:"Dalam urutan hadis tentang rukun Islam, zakat berada di urutan ke berapa?",c:["Ke-3","Ke-1","Ke-5","Ke-2"],b:0,e:"Syahadat, salat, zakat, haji, puasa Ramadan.",s:['h:piliers']},
  {q:"Makna apa yang terkandung dalam kata “zakat” dalam bahasa Arab?",c:["Penyucian dan pertumbuhan","Kesabaran","Kemenangan","Cahaya"],b:0,e:"Al-Qur'an menyebut bahwa sedekah itu membersihkan (tuṭahhiruhum) dan menyucikan serta menumbuhkan kebaikan (tuzakkîhim).",s:['q:9:103']}
 ]},
'p-hajj':{titre:"Haji, ziarah ke Baitullah",
 texte:["Haji adalah ziarah ke Mekah, salah satu dari lima rukun Islam. Haji wajib sekali seumur hidup bagi yang mampu secara fisik dan finansial.",
  "Haji dilaksanakan pada bulan Zulhijah. Jemaah memasuki keadaan ihram, melakukan tujuh putaran mengelilingi Kakbah (tawaf) dan tujuh kali perjalanan antara Safa dan Marwah (sai). Momen terpentingnya adalah wukuf di Arafah, pada tanggal 9 Zulhijah.",
  "Keesokan harinya, umat Islam di seluruh dunia merayakan Iduladha, hari raya kurban, untuk mengenang Nabi Ibrahim."],
 retenir:"Sekali seumur hidup. Arafah pada 9 Zulhijah, Iduladha pada tanggal 10.",
 sources:['q:3:97','q:22:27','h:hajj_pardon'],
 quiz:[
  {q:"Di kota mana ibadah haji dilaksanakan?",c:["Mekah","Madinah","Yerusalem","Taif"],b:0,e:"Haji dilaksanakan di Mekah dan sekitarnya.",s:['q:3:97']},
  {q:"Pada bulan apa dalam kalender Islam ibadah haji dilaksanakan?",c:["Zulhijah","Ramadan","Muharram","Syawal"],b:0,e:"Haji berlangsung dari tanggal 8 sampai 13 Zulhijah.",s:['f:hajj']},
  {q:"Menurut hadis, apa unsur terpenting dalam ibadah haji?",c:["Wukuf di Arafah","Salat di Masjid Al-Aqsa","Ziarah ke Madinah","Mengunjungi Gua Hira"],b:0,e:"“Haji itu adalah Arafah.”",s:['h:arafa']},
  {q:"Hari raya apa yang dirayakan sehari setelah hari Arafah?",c:["Iduladha","Idulfitri","Maulid","1 Muharram"],b:0,e:"Tanggal 10 Zulhijah adalah Iduladha.",s:['f:hajj']},
  {q:"Menurut hadis, bagaimana keadaan jemaah yang berhaji tanpa berbuat dosa dan tanpa berkata kotor saat ia pulang?",c:["Seperti pada hari ia dilahirkan ibunya","Lebih kaya","Dibebaskan dari puasa","Dengan gelar haji, tanpa pahala lainnya"],b:0,e:"Ia pulang dalam keadaan bersih dari dosa-dosanya.",s:['h:hajj_pardon']},
  {q:"Nabi siapa yang diperintahkan untuk menyeru manusia agar berhaji?",c:["Ibrahim","Musa","Nuh","Yusuf"],b:0,e:"Allah memerintahkan Ibrahim untuk menyeru manusia agar berhaji.",s:['q:22:27']},
  {q:"Apa nama keadaan suci yang dimasuki oleh jemaah haji?",c:["Ihram","Wudu","Iktikaf","Tayamum"],b:0,e:"Laki-laki mengenakan dua helai kain putih yang tidak berjahit.",s:['f:hajj']},
  {q:"Apa nama tujuh putaran mengelilingi Kakbah?",c:["Tawaf","Sai","Rakaat","Zikir"],b:0,e:"Tawaf dilakukan sebanyak tujuh putaran, dengan Kakbah berada di sebelah kiri.",s:['f:hajj']},
  {q:"Di antara dua bukit manakah jemaah haji melakukan tujuh kali perjalanan?",c:["Safa dan Marwah","Arafah dan Mina","Uhud dan Tsur","Hira dan Tsur"],b:0,e:"Al-Qur'an menyebut Safa dan Marwah sebagai bagian dari syiar-syiar Allah.",s:['q:2:158']},
  {q:"Untuk mengenang nabi siapa umat Islam menyembelih hewan kurban pada hari Iduladha?",c:["Ibrahim","Isa","Musa","Daud"],b:0,e:"Allah menebus putra Ibrahim dengan sembelihan yang besar.",s:['q:37:107']}
 ]},

/* ===================== AL-QUR'AN ===================== */
'c-coran':{titre:"Al-Qur'an, firman Allah",
 texte:["Al-Qur'an adalah firman Allah, yang diwahyukan dalam bahasa Arab kepada Nabi Muhammad ﷺ melalui perantaraan Malaikat Jibril.",
  "Wahyu pertama turun di Gua Hira, dekat Mekah, ketika Nabi ﷺ berusia 40 tahun. Kata-kata pertama yang diwahyukan diawali dengan “Iqra'”: “Bacalah!”.",
  "Pewahyuan berlangsung sekitar 23 tahun. Al-Qur'an terdiri dari 114 surah; Allah sendiri yang menjamin pemeliharaannya."],
 retenir:"114 surah, diwahyukan selama 23 tahun. Kata pertama: “Iqra'”, “Bacalah!”.",
 sources:['q:96:1','h:hira','q:15:9'],
 quiz:[
  {q:"Berapa jumlah surah dalam Al-Qur'an?",c:["114","99","120","30"],b:0,e:"Al-Qur'an terdiri dari 114 surah.",s:['f:coran']},
  {q:"Malaikat siapa yang menyampaikan Al-Qur'an kepada Nabi Muhammad ﷺ?",c:["Jibril","Mikail","Israfil","Malik"],b:0,e:"Malaikat Jibril-lah yang menyampaikan wahyu.",s:['q:2:97']},
  {q:"Di gua mana Nabi ﷺ menerima wahyu Al-Qur'an yang pertama?",c:["Gua Hira","Gua Tsur","Sebuah gua di Madinah","Sebuah gua di Yerusalem"],b:0,e:"Gua Hira terletak di Jabal Nur, dekat Mekah.",s:['h:hira']},
  {q:"Apa arti “Iqra'”, kata pertama Al-Qur'an yang diwahyukan?",c:["Bacalah!","Salatlah!","Dengarlah!","Berpuasalah!"],b:0,e:"Inilah awal surah Al-'Alaq (96).",s:['q:96:1']},
  {q:"Kira-kira selama berapa tahun Al-Qur'an diwahyukan?",c:["23 tahun","1 tahun","40 tahun","10 tahun"],b:0,e:"Sekitar 13 tahun di Mekah dan 10 tahun di Madinah.",s:['h:vie']},
  {q:"Menjadi berapa bagian (juz) Al-Qur'an dibagi untuk dibaca?",c:["30","114","7","12"],b:0,e:"Tiga puluh juz: misalnya satu juz setiap hari selama Ramadan.",s:['f:coran']},
  {q:"Dalam bahasa apa Al-Qur'an diwahyukan?",c:["Bahasa Arab","Bahasa Ibrani","Bahasa Persia","Bahasa Aram"],b:0,e:"“Sesungguhnya Kami menurunkannya berupa Al-Qur'an berbahasa Arab.”",s:['q:12:2']},
  {q:"Menurut Al-Qur'an, siapa yang menjamin terpeliharanya Al-Qur'an?",c:["Allah","Hanya para ulama","Para khalifah","Tidak ada siapa pun"],b:0,e:"“Sesungguhnya Kami-lah yang menurunkan Al-Qur'an, dan sesungguhnya Kami benar-benar memeliharanya.”",s:['q:15:9']},
  {q:"Berapa usia Nabi ﷺ ketika menerima wahyu pertama?",c:["40 tahun","25 tahun","63 tahun","13 tahun"],b:0,e:"Beliau mulai menerima wahyu pada usia 40 tahun.",s:['h:vie']},
  {q:"Apa sebutan untuk satu ayat Al-Qur'an dalam bahasa Arab?",c:["Âyah (ayat)","Surah","Juz","Hadis"],b:0,e:"Satu ayat disebut âyah; satu bab disebut surah.",s:['f:coran']}
 ]},
'c-sourates':{titre:"Surah-surah Al-Qur'an",
 texte:["Al-Qur'an terdiri dari 114 surah dengan panjang yang sangat beragam. Setiap surah dimulai dengan basmalah, kecuali surah At-Taubah.",
  "Surah pertama adalah Al-Fatihah, “Pembukaan”. Yang terpanjang adalah Al-Baqarah, “Sapi Betina”, dengan 286 ayat. Yang terpendek adalah Al-Kautsar, dengan 3 ayat. Yang terakhir adalah An-Nas, “Manusia”.",
  "Surah-surah yang diwahyukan sebelum Hijrah disebut Makkiyah, sedangkan yang diwahyukan sesudahnya disebut Madaniyah."],
 retenir:"Pertama: Al-Fatihah. Terpanjang: Al-Baqarah. Terpendek: Al-Kautsar. Terakhir: An-Nas.",
 sources:['q:1:1','q:108:1','q:114:1'],
 quiz:[
  {q:"Apa surah pertama dalam Al-Qur'an?",c:["Al-Fatihah","Al-Baqarah","An-Nas","Al-'Alaq"],b:0,e:"Al-Fatihah membuka Al-Qur'an. Al-'Alaq memuat ayat-ayat yang pertama kali diwahyukan, tetapi ia adalah surah ke-96.",s:['q:1:1']},
  {q:"Apa surah terpanjang dalam Al-Qur'an?",c:["Al-Baqarah","Al-Fatihah","Al-Kautsar","Yasin"],b:0,e:"Al-Baqarah, surah ke-2, terdiri dari 286 ayat.",s:['f:coran']},
  {q:"Apa surah terpendek dalam Al-Qur'an?",c:["Al-Kautsar","Al-Ikhlas","An-Nas","Al-'Asr"],b:0,e:"Al-Kautsar, surah ke-108, terdiri dari 3 ayat.",s:['q:108:1']},
  {q:"Apa surah terakhir dalam Al-Qur'an?",c:["An-Nas","Al-Falaq","Al-Ikhlas","Al-Fatihah"],b:0,e:"An-Nas, “Manusia”, adalah surah ke-114.",s:['q:114:1']},
  {q:"Surah apa yang dimulai dengan “Qul huwa Llâhu aḥad”?",c:["Al-Ikhlas","An-Nas","Al-Falaq","Al-Kafirun"],b:0,e:"“Katakanlah: Dialah Allah, Yang Maha Esa.”",s:['q:112:1']},
  {q:"Surah apa yang memuat ayat “Kitab (Al-Qur'an) ini tidak ada keraguan padanya”?",c:["Al-Baqarah","Al-Fatihah","Maryam","Yasin"],b:0,e:"Inilah ayat ke-2 surah Al-Baqarah.",s:['q:2:2']},
  {q:"Surah apa yang dinamai dengan nama ibu Nabi Isa?",c:["Maryam","Ali Imran","An-Nisa","Taha"],b:0,e:"Surah ke-19 dinamai dengan nama Maryam.",s:['q:19:16']},
  {q:"Apa satu-satunya surah yang tidak dimulai dengan “Bismi Llâhi r-Raḥmâni r-Raḥîm”?",c:["At-Taubah (surah ke-9)","Al-Fatihah","An-Nas","Al-Baqarah"],b:0,e:"At-Taubah adalah satu-satunya dari 114 surah yang tidak diawali basmalah.",s:['f:tawba']},
  {q:"Apa sebutan untuk kalimat “Bismi Llâhi r-Raḥmâni r-Raḥîm”?",c:["Basmalah","Syahadat","Takbir","Talbiyah"],b:0,e:"Artinya: “Dengan nama Allah Yang Maha Pengasih, Maha Penyayang”.",s:['q:1:1']},
  {q:"Apa sebutan untuk surah-surah yang diwahyukan di Mekah, sebelum Hijrah?",c:["Surah Makkiyah","Surah Madaniyah","Surah-surah panjang","Surah-surah Taif"],b:0,e:"Surah yang diwahyukan setelah Hijrah disebut Madaniyah.",s:['f:coran']}
 ]},
'c-ikhlas':{titre:"Al-Ikhlas dan Ayat Kursi",
 texte:["Surah Al-Ikhlas (112) merangkum keimanan akan keesaan Allah: Dia Maha Esa, tidak beranak dan tidak diperanakkan, dan tidak ada sesuatu pun yang setara dengan-Nya.",
  "Nabi ﷺ bersabda bahwa surah ini setara dengan sepertiga Al-Qur'an.",
  "Ayat Kursi (surah ke-2, ayat 255) adalah ayat paling agung dalam Al-Qur'an. Ayat ini menggambarkan kehidupan, ilmu, dan kekuasaan Allah."],
 retenir:"Al-Ikhlas setara dengan sepertiga Al-Qur'an. Ayat Kursi adalah ayat paling agung.",
 sources:['q:112:1','h:ikhlas','h:kursi'],
 quiz:[
  {q:"Apa arti “Qul huwa Llâhu aḥad”?",c:["Katakanlah: Dialah Allah, Yang Maha Esa","Dengan nama Allah","Allah Maha Besar","Maha Suci Allah"],b:0,e:"Inilah ayat pertama surah Al-Ikhlas.",s:['q:112:1']},
  {q:"Menurut hadis, surah Al-Ikhlas setara dengan berapa bagian Al-Qur'an?",c:["Sepertiga","Setengah","Sepersepuluh","Seluruh Al-Qur'an"],b:0,e:"Nabi ﷺ bersabda bahwa surah ini setara dengan sepertiga Al-Qur'an.",s:['h:ikhlas']},
  {q:"Berapa jumlah ayat surah Al-Ikhlas?",c:["4","7","3","5"],b:0,e:"Surah Al-Ikhlas terdiri dari 4 ayat.",s:['q:112:4']},
  {q:"Menurut surah Al-Ikhlas, adakah sesuatu yang setara dengan Allah?",c:["Tidak, tidak ada yang setara dengan-Nya","Ya, para malaikat","Ya, para nabi","Ya, para jin"],b:0,e:"“Dan tidak ada sesuatu pun yang setara dengan Dia.”",s:['q:112:4']},
  {q:"Menurut hadis, apa ayat paling agung dalam Al-Qur'an?",c:["Ayat Kursi","Ayat pertama Al-Fatihah","Ayat terakhir Al-Qur'an","Ayat tentang cahaya (An-Nur)"],b:0,e:"Ubay bin Ka'ab mengatakannya kepada Nabi ﷺ, dan beliau membenarkannya.",s:['h:kursi']},
  {q:"Dalam surah apa Ayat Kursi berada?",c:["Al-Baqarah, ayat 255","Al-Fatihah, ayat 1","Yasin, ayat 1","Al-Ikhlas, ayat 2"],b:0,e:"Ayat Kursi adalah ayat ke-255 surah Al-Baqarah.",s:['q:2:255']},
  {q:"Menurut Ayat Kursi, apakah Allah ditimpa kantuk atau tidur?",c:["Tidak, Dia tidak mengantuk dan tidak tidur","Ya, pada malam hari","Ya, kadang-kadang","Hanya tidur"],b:0,e:"Allah Yang Maha Hidup, Yang terus-menerus mengurus makhluk-Nya.",s:['q:2:255']},
  {q:"Apa arti “Allâhu ṣ-ṣamad” dalam surah Al-Ikhlas?",c:["Allah adalah tempat semua makhluk bergantung, dan Dia tidak membutuhkan siapa pun","Allah adalah Pencipta langit","Allah Maha Pengampun","Allah Maha Hakim"],b:0,e:"Ash-Shamad adalah salah satu nama Allah.",s:['q:112:2']},
  {q:"Apa arti nama surah “Al-Ikhlas”?",c:["Tauhid yang murni, ketulusan","Waktu fajar","Kemenangan","Manusia"],b:0,e:"Surah ini memurnikan iman dari segala bentuk syirik.",s:['f:ikhlas']},
  {q:"Menurut Ayat Kursi, seberapa banyak ilmu-Nya yang Allah berikan kepada makhluk-Nya?",c:["Hanya apa yang Dia kehendaki","Seluruh ilmu-Nya","Tidak sedikit pun","Setengahnya"],b:0,e:"“Dan mereka tidak mengetahui sesuatu apa pun dari ilmu-Nya melainkan apa yang Dia kehendaki.”",s:['q:2:255']}
 ]},

/* ===================== PARA NABI ===================== */
'pr-adam':{titre:"Adam dan Nuh",
 texte:["Adam adalah manusia pertama dan nabi pertama. Allah mengajarinya nama segala sesuatu, lalu memerintahkan para malaikat untuk sujud kepadanya. Iblis menolak karena sombong.",
  "Nuh menyeru kaumnya untuk menyembah Allah semata selama 950 tahun. Hanya sedikit orang yang mengikutinya, bahkan putranya sendiri tidak.",
  "Atas perintah Allah, Nuh membangun bahtera, yang menyelamatkannya dari banjir besar bersama orang-orang beriman dan pasangan-pasangan hewan."],
 retenir:"Adam, manusia pertama. Nuh, 950 tahun berdakwah, dan bahteranya.",
 sources:['q:2:31','q:2:34','q:29:14'],
 quiz:[
  {q:"Siapa nabi pertama umat manusia?",c:["Adam","Nuh","Ibrahim","Musa"],b:0,e:"Adam adalah manusia pertama dan nabi pertama.",s:['q:2:31']},
  {q:"Apa yang Allah ajarkan kepada Adam?",c:["Nama segala sesuatu","Hafalan Al-Qur'an","Hanya bahasa para malaikat","Hanya nama-nama para nabi"],b:0,e:"“Dan Dia mengajarkan kepada Adam nama-nama (benda) semuanya.”",s:['q:2:31']},
  {q:"Siapa yang menolak sujud kepada Adam?",c:["Iblis","Jibril","Mikail","Semua malaikat"],b:0,e:"Para malaikat sujud, kecuali Iblis.",s:['q:2:34']},
  {q:"Mengapa Iblis menolak sujud kepada Adam?",c:["Karena sombong","Karena lupa","Karena takut","Karena tidak mendengar perintahnya"],b:0,e:"Ia menolak dan menyombongkan diri, dan ia termasuk golongan yang kafir.",s:['q:2:34']},
  {q:"Di mana Adam dan istrinya tinggal sebelum turun ke bumi?",c:["Di surga","Di Mekah","Di Mesir","Di Yerusalem"],b:0,e:"“Tinggallah engkau dan istrimu di dalam surga.”",s:['q:2:35']},
  {q:"Nabi siapa yang membangun bahtera atas perintah Allah?",c:["Nuh","Yunus","Sulaiman","Isa"],b:0,e:"Nuh membangun bahtera di bawah pengawasan Allah dan sesuai dengan wahyu-Nya.",s:['q:11:37']},
  {q:"Menurut Al-Qur'an, berapa lama Nuh tinggal bersama kaumnya?",c:["950 tahun","40 tahun","100 tahun","313 tahun"],b:0,e:"“Seribu tahun kurang lima puluh tahun.”",s:['q:29:14']},
  {q:"Siapa yang selamat di dalam bahtera Nuh?",c:["Nuh, orang-orang beriman, dan pasangan-pasangan hewan","Seluruh kaumnya","Hanya hewan-hewan","Tidak ada seorang pun"],b:0,e:"Allah memerintahkan agar dinaikkan sepasang dari setiap jenis, keluarganya, dan orang-orang beriman.",s:['q:11:40']},
  {q:"Apakah putra Nuh naik ke dalam bahtera?",c:["Tidak, ia menolak dan ditenggelamkan","Ya, paling pertama","Ya, paling akhir","Nuh tidak punya putra"],b:0,e:"Ia mengira bisa berlindung di atas gunung, tetapi gelombang menenggelamkannya.",s:['q:11:43']},
  {q:"Menurut tradisi Islam, siapa nama istri Adam?",c:["Hawa","Maryam","Asiyah","Hajar"],b:0,e:"Al-Qur'an menyebutnya tanpa menyebut namanya; namanya berasal dari Sunah.",s:['f:hawwa']}
 ]},
'pr-ibrahim':{titre:"Ibrahim, kekasih Allah",
 texte:["Ibrahim menolak menyembah berhala-berhala kaumnya. Ia dilemparkan ke dalam api yang besar, tetapi Allah memerintahkan api itu agar menjadi dingin dan keselamatan baginya.",
  "Allah menjadikannya kekasih (khalil). Ia adalah ayah dari dua nabi: Ismail dan Ishaq.",
  "Bersama putranya Ismail, ia meninggikan fondasi Kakbah. Kurban pada hari Iduladha mengingatkan pada ketaatannya kepada Allah."],
 retenir:"Ibrahim, kekasih Allah, diselamatkan dari api, pembangun Kakbah bersama Ismail.",
 sources:['q:21:69','q:4:125','q:2:127'],
 quiz:[
  {q:"Nabi siapa yang meninggikan fondasi Kakbah bersama putranya Ismail?",c:["Ibrahim","Musa","Daud","Adam"],b:0,e:"Ibrahim dan putranya Ismail meninggikan fondasi Kakbah.",s:['q:2:127']},
  {q:"Apa yang terjadi pada Ibrahim ketika kaumnya melemparkannya ke dalam api?",c:["Allah menjadikan api itu dingin dan tidak membahayakannya","Ia melarikan diri","Ia terluka","Ia diselamatkan oleh hujan"],b:0,e:"“Wahai api! Jadilah dingin, dan penyelamat bagi Ibrahim.”",s:['q:21:69']},
  {q:"Gelar apa yang diberikan Al-Qur'an kepada Nabi Ibrahim?",c:["Kekasih Allah (Khalil)","Penutup para nabi","Orang yang diajak bicara langsung oleh Allah","Ruh Allah"],b:0,e:"“Dan Allah telah memilih Ibrahim menjadi kekasih-Nya.”",s:['q:4:125']},
  {q:"Siapa dua putra Ibrahim yang menjadi nabi?",c:["Ismail dan Ishaq","Musa dan Harun","Daud dan Sulaiman","Yahya dan Isa"],b:0,e:"Ibrahim bersyukur kepada Allah karena dianugerahi Ismail dan Ishaq di masa tuanya.",s:['q:14:39']},
  {q:"Apa yang dilakukan kaum Ibrahim, yang ia tolak?",c:["Menyembah patung-patung","Berpuasa","Bersedekah","Berhaji"],b:0,e:"Ia bertanya kepada mereka: “Patung-patung apakah ini yang kamu tekun menyembahnya?”",s:['q:21:52']},
  {q:"Dengan apa Allah menebus putra Ibrahim saat ia hendak disembelih?",c:["Dengan sembelihan yang besar (seekor hewan kurban)","Dengan sedekah emas","Dengan puasa ayahnya","Dengan salat malam"],b:0,e:"Menurut riwayat, sembelihan itu adalah seekor domba jantan (kibas).",s:['q:37:107']},
  {q:"Hari raya apa yang mengingatkan pada ketaatan Ibrahim kepada Allah?",c:["Iduladha","Idulfitri","1 Muharram","Maulid"],b:0,e:"Kurban pada hari Iduladha memperingati ujian yang dialaminya.",s:['q:37:107']},
  {q:"Menurut Al-Qur'an, bagaimana Ibrahim digambarkan?",c:["Seorang yang lurus bertauhid (hanif), bukan Yahudi dan bukan Nasrani","Seorang raja Babilonia","Seorang malaikat","Seorang penyair"],b:0,e:"Ia berserah diri sepenuhnya kepada Allah.",s:['q:3:67']},
  {q:"Putra mana yang membantu Ibrahim meninggikan fondasi Kakbah?",c:["Ismail","Ishaq","Yakub","Yusuf"],b:0,e:"Ibrahim dan Ismail bersama-sama meninggikan fondasi Baitullah.",s:['q:2:127']},
  {q:"Menurut Al-Qur'an, apa rumah ibadah pertama yang dibangun untuk manusia?",c:["Yang di Bakkah (Mekah)","Yang di Yerusalem","Yang di Madinah","Yang di Taif"],b:0,e:"Bakkah adalah salah satu nama kota Mekah.",s:['q:3:96']}
 ]},
'pr-yunus':{titre:"Yunus, Yusuf, dan Sulaiman",
 texte:["Yunus ditelan oleh seekor ikan besar. Dalam kegelapan, ia berdoa kepada Allah, dan Allah menyelamatkannya dari kesedihan.",
  "Kisah Yusuf, yang dikhianati saudara-saudaranya lalu menjadi pejabat tinggi di Mesir, memenuhi seluruh surah ke-12: “kisah yang paling baik”.",
  "Sulaiman, putra Daud, dianugerahi kerajaan yang sangat besar dan memahami bahasa burung dan semut."],
 retenir:"Yunus dan ikan besar. Yusuf, surah ke-12. Sulaiman dan bahasa hewan.",
 sources:['q:37:142','q:12:3','q:27:18'],
 quiz:[
  {q:"Nabi siapa yang ditelan oleh seekor ikan besar?",c:["Yunus","Yusuf","Ayyub","Luth"],b:0,e:"Yunus ditelan ikan, lalu Allah menyelamatkannya.",s:['q:37:142']},
  {q:"Surah Al-Qur'an apa yang menceritakan seluruh kisah Nabi Yusuf?",c:["Surah ke-12, Yusuf","Surah ke-1, Al-Fatihah","Surah ke-36, Yasin","Surah ke-112, Al-Ikhlas"],b:0,e:"Surah ke-12 dinamai dengan namanya.",s:['q:12:3']},
  {q:"Nabi siapa yang memahami bahasa semut?",c:["Sulaiman","Saleh","Hud","Zakaria"],b:0,e:"Sulaiman mendengar seekor semut memperingatkan semut-semut lainnya, dan ia tersenyum mendengar perkataannya.",s:['q:27:18']},
  {q:"Doa apa yang diucapkan Yunus di dalam perut ikan?",c:["“Lâ ilâha illâ anta, subḥânaka, innî kuntu mina ẓ-ẓâlimîn”","“Bismi Llâh”","“Allâhu akbar”","“Rabbanâ âtinâ”"],b:0,e:"“Tidak ada tuhan selain Engkau, Maha Suci Engkau. Sungguh, aku termasuk orang-orang yang zalim.”",s:['q:21:87']},
  {q:"Bagaimana Allah menjawab doa Yunus?",c:["Dia menyelamatkannya dari kesedihan","Dia membiarkannya di dalam ikan","Dia membiarkannya tiga tahun di dalam ikan","Dia tidak menjawabnya"],b:0,e:"“Maka Kami kabulkan doanya dan Kami selamatkan dia dari kedukaan.”",s:['q:21:88']},
  {q:"Dalam mimpinya semasa kecil, berapa bintang yang dilihat Yusuf bersujud kepadanya?",c:["Sebelas, bersama matahari dan bulan","Tujuh","Dua belas","Hanya satu"],b:0,e:"Sebelas bintang, matahari, dan bulan.",s:['q:12:4']},
  {q:"Siapa yang melemparkan Yusuf ke dasar sumur?",c:["Saudara-saudaranya","Firaun","Para pedagang","Ayahnya"],b:0,e:"Saudara-saudaranya yang iri memutuskan untuk melemparkannya ke dasar sumur.",s:['q:12:15']},
  {q:"Al-Qur'an menyebut kisah Yusuf sebagai apa?",c:["Kisah yang paling baik","Kisah tentang api","Kitab hikmah","Kisah tentang bahtera"],b:0,e:"“Kami menceritakan kepadamu kisah yang paling baik.”",s:['q:12:3']},
  {q:"Nabi siapa yang dianugerahi pengetahuan tentang bahasa burung?",c:["Sulaiman","Yunus","Nuh","Hud"],b:0,e:"“Kami telah diajari bahasa burung,” kata Sulaiman.",s:['q:27:16']},
  {q:"Siapa ayah Sulaiman, yang juga seorang nabi dan raja?",c:["Daud","Ibrahim","Yakub","Musa"],b:0,e:"“Dan Sulaiman telah mewarisi Daud.”",s:['q:27:16']}
 ]},
'pr-musa':{titre:"Musa, yang diajak bicara oleh Allah",
 texte:["Musa lahir di Mesir, pada masa ketika Firaun menindas Bani Israil. Atas ilham dari Allah, ibunya menghanyutkannya di sungai, lalu keluarga Firaun memungutnya.",
  "Allah berbicara langsung kepadanya dan mengutusnya kepada Firaun bersama saudaranya Harun, dengan membawa mukjizat-mukjizat, seperti tongkatnya yang berubah menjadi ular.",
  "Allah membelah laut untuk menyelamatkan Musa dan kaumnya, dan Firaun ditenggelamkan. Musa adalah nabi yang paling sering disebut dalam Al-Qur'an."],
 retenir:"Musa, diselamatkan dari air, Kalimullah, laut yang terbelah.",
 sources:['q:28:7','q:4:164','q:26:63'],
 quiz:[
  {q:"Di negeri mana Nabi Musa lahir?",c:["Di Mesir","Di Arab","Di Irak","Di Yaman"],b:0,e:"Ia lahir di Mesir, pada masa pemerintahan Firaun.",s:['q:28:7']},
  {q:"Apa yang dilakukan ibu Musa untuk melindunginya dari Firaun?",c:["Ia menghanyutkannya di sungai","Ia menyembunyikannya di dalam gua","Ia pergi ke padang pasir","Ia menitipkannya kepada seorang penggembala"],b:0,e:"Allah mengilhaminya untuk menghanyutkannya ke sungai, tanpa rasa takut.",s:['q:28:7']},
  {q:"Siapa yang memungut bayi Musa dari sungai?",c:["Keluarga Firaun","Para nelayan","Ibrahim","Seorang raja Yaman"],b:0,e:"Keluarga Firaun memungutnya.",s:['q:28:8']},
  {q:"Nabi siapa yang disebut “Kalîm Allâh” (Kalimullah), yang diajak bicara langsung oleh Allah?",c:["Musa","Ibrahim","Isa","Nuh"],b:0,e:"“Dan kepada Musa, Allah berfirman secara langsung.”",s:['q:4:164']},
  {q:"Menjadi apa tongkat Musa ketika ia melemparkannya ke tanah?",c:["Seekor ular","Sebatang pohon","Seekor merpati","Sebilah pedang"],b:0,e:"“Lalu ia melemparkannya, maka tiba-tiba tongkat itu menjadi seekor ular yang merayap dengan cepat.”",s:['q:20:20']},
  {q:"Apa yang terjadi ketika Musa memukul laut dengan tongkatnya?",c:["Laut terbelah menjadi dua","Laut berubah menjadi pasir","Laut tiba-tiba mengering","Tidak terjadi apa-apa"],b:0,e:"Setiap belahan seperti gunung yang besar.",s:['q:26:63']},
  {q:"Apa yang terjadi pada Firaun dan bala tentaranya yang mengejar Musa?",c:["Mereka ditenggelamkan oleh laut","Mereka masuk Islam","Mereka kembali ke Mesir","Mereka juga berhasil menyeberang"],b:0,e:"Allah menyelamatkan Musa dan orang-orang yang bersamanya, dan menenggelamkan yang lain.",s:['q:26:66']},
  {q:"Siapa nama saudara Musa yang membantunya dalam menjalankan tugasnya?",c:["Harun","Yusuf","Ishaq","Yahya"],b:0,e:"Musa memohon kepada Allah agar menjadikan saudaranya Harun sebagai pembantunya.",s:['q:20:30']},
  {q:"Kepada raja mana Allah mengutus Musa?",c:["Firaun","Namrud","Raja negeri Saba","Jalut"],b:0,e:"“Pergilah kepada Firaun; sesungguhnya dia telah melampaui batas.”",s:['q:20:24']},
  {q:"Nabi siapa yang paling sering disebut namanya dalam Al-Qur'an?",c:["Musa","Muhammad ﷺ","Ibrahim","Nuh"],b:0,e:"Nama Musa disebut lebih dari 130 kali dalam Al-Qur'an.",s:['f:musa']}
 ]},
'pr-isa':{titre:"Isa dan Maryam",
 texte:["Maryam, ibu Isa, adalah satu-satunya perempuan yang disebut namanya dalam Al-Qur'an. Allah memilihnya di atas seluruh perempuan di semesta alam, dan sebuah surah dinamai dengan namanya.",
  "Isa lahir tanpa ayah, atas kehendak Allah, sebagaimana Adam diciptakan tanpa ayah dan ibu. Ketika masih bayi, ia berbicara dari buaiannya.",
  "Bagi umat Islam, Isa adalah seorang nabi besar dan utusan Allah, Al-Masih, yang kepadanya diturunkan Injil."],
 retenir:"Maryam, yang dipilih di antara para perempuan. Isa, lahir tanpa ayah, nabi dan Al-Masih.",
 sources:['q:3:42','q:3:59','q:19:30'],
 quiz:[
  {q:"Siapa satu-satunya perempuan yang disebut namanya dalam Al-Qur'an?",c:["Maryam","Khadijah","Asiyah","Hawa"],b:0,e:"Maryam adalah satu-satunya perempuan yang disebut namanya; surah ke-19 dinamai dengan namanya.",s:['f:maryam']},
  {q:"Apa yang dikatakan Al-Qur'an tentang Maryam?",c:["Allah memilihnya di atas seluruh perempuan di semesta alam","Ia adalah ratu Mesir","Ia adalah nabi perempuan dari Madinah","Al-Qur'an tidak membicarakannya"],b:0,e:"Para malaikat mengabarkan kepadanya bahwa Allah telah memilih dan menyucikannya.",s:['q:3:42']},
  {q:"Bagaimana Nabi Isa dilahirkan?",c:["Tanpa ayah, atas kehendak Allah","Seperti manusia pada umumnya","Di istana Firaun","Di Mekah"],b:0,e:"Allah berfirman “Jadilah!”, maka jadilah ia.",s:['q:3:59']},
  {q:"Dengan penciptaan siapa Al-Qur'an menyamakan penciptaan Isa?",c:["Dengan penciptaan Adam","Dengan penciptaan para malaikat","Dengan penciptaan Nuh","Dengan penciptaan Iblis"],b:0,e:"Adam diciptakan tanpa ayah dan ibu; Isa tanpa ayah.",s:['q:3:59']},
  {q:"Mukjizat apa yang dilakukan Isa ketika masih bayi?",c:["Ia berbicara dari buaiannya","Ia berjalan di atas air","Ia memancarkan air Zamzam","Ia menyeberangi laut"],b:0,e:"Ia membela ibunya dengan berbicara dari buaian.",s:['q:19:30']},
  {q:"Menurut Al-Qur'an, apa kata-kata pertama Isa ketika masih bayi?",c:["“Aku adalah hamba Allah”","“Aku adalah raja”","“Aku adalah malaikat”","“Aku adalah putra Zakaria”"],b:0,e:"“Sesungguhnya aku hamba Allah. Dia memberiku Kitab dan menjadikan aku seorang nabi.”",s:['q:19:30']},
  {q:"Gelar apa yang diberikan Al-Qur'an kepada Isa?",c:["Al-Masih","Al-Khalil","Penutup para nabi","Kalimullah"],b:0,e:"Para malaikat mengabarkan kepada Maryam: “namanya Al-Masih, Isa putra Maryam”.",s:['q:3:45']},
  {q:"Kitab apa yang Allah turunkan kepada Nabi Isa?",c:["Injil","Taurat","Zabur","Al-Qur'an"],b:0,e:"“Dan Kami menurunkan Injil kepadanya, di dalamnya terdapat petunjuk dan cahaya.”",s:['q:5:46']},
  {q:"Bagi umat Islam, siapakah Isa?",c:["Seorang nabi dan utusan Allah","Seorang tuhan","Seorang malaikat","Seorang raja Yerusalem"],b:0,e:"Ia sendiri memperkenalkan dirinya sebagai hamba Allah dan nabi.",s:['q:19:30']},
  {q:"Siapa yang diutus kepada Maryam untuk mengabarkan kelahiran Isa?",c:["Ruh Allah, Malaikat Jibril","Zakaria","Yahya","Malaikat Mikail"],b:0,e:"Para ulama menjelaskan bahwa “Ruh Kami” yang dimaksud adalah Malaikat Jibril.",s:['q:19:19']}
 ]},
'pr-muhammad':{titre:"Muhammad ﷺ, nabi terakhir",
 texte:["Muhammad ﷺ lahir di Mekah sekitar tahun 570, pada “Tahun Gajah”, dari suku Quraisy. Ayahnya wafat sebelum beliau lahir, ibunya Aminah wafat ketika beliau berusia 6 tahun, lalu beliau diasuh oleh kakeknya, kemudian oleh pamannya Abu Thalib.",
  "Beliau dikenal karena kejujurannya dan dijuluki Al-Amin, “yang dapat dipercaya”. Beliau menerima wahyu pertama pada usia 40 tahun.",
  "Beliau wafat di Madinah pada tahun 632, dalam usia 63 tahun. Allah mengutusnya sebagai rahmat bagi seluruh alam."],
 retenir:"Lahir di Mekah sekitar tahun 570, menerima wahyu pada usia 40 tahun, wafat di Madinah pada usia 63 tahun.",
 sources:['q:21:107','q:68:4','h:vie'],
 quiz:[
  {q:"Di kota mana Nabi Muhammad ﷺ lahir?",c:["Mekah","Madinah","Yerusalem","Taif"],b:0,e:"Beliau lahir di Mekah sekitar tahun 570.",s:['f:sira']},
  {q:"Apa sebutan untuk tahun kelahiran Nabi ﷺ?",c:["Tahun Gajah","Tahun Hijrah","Tahun Kesedihan","Tahun Kemenangan"],b:0,e:"Tahun ketika pasukan yang datang dengan gajah-gajah menyerang Mekah (surah ke-105).",s:['q:105:1']},
  {q:"Siapa nama ibu Nabi ﷺ?",c:["Aminah","Khadijah","Halimah","Fatimah"],b:0,e:"Aminah binti Wahb wafat ketika beliau berusia 6 tahun.",s:['f:sira']},
  {q:"Paman mana yang mengasuh dan melindungi Nabi ﷺ?",c:["Abu Thalib","Abu Lahab","Hamzah","Al-Abbas"],b:0,e:"Setelah kakeknya wafat, pamannya Abu Thalib mengasuhnya.",s:['f:sira']},
  {q:"Julukan apa yang diberikan penduduk Mekah kepada Nabi ﷺ sebelum masa kenabian?",c:["Al-Amin, yang dapat dipercaya","Al-Faruq","Ash-Shiddiq","Saifullah"],b:0,e:"Beliau dikenal semua orang karena kejujurannya.",s:['f:sira']},
  {q:"Pada usia berapa Nabi ﷺ wafat?",c:["63 tahun","40 tahun","70 tahun","53 tahun"],b:0,e:"Ibnu Abbas meriwayatkan bahwa beliau wafat pada usia 63 tahun.",s:['h:vie']},
  {q:"Di kota mana Nabi ﷺ wafat?",c:["Madinah","Mekah","Yerusalem","Damaskus"],b:0,e:"Beliau wafat di Madinah pada tahun 632 dan dimakamkan di sana.",s:['f:sira']},
  {q:"Menurut Al-Qur'an, untuk apa Allah mengutus Muhammad ﷺ?",c:["Sebagai rahmat bagi seluruh alam","Untuk menjadi raja","Untuk menghukum manusia","Hanya untuk bangsa Arab"],b:0,e:"“Dan Kami tidak mengutus engkau melainkan untuk menjadi rahmat bagi seluruh alam.”",s:['q:21:107']},
  {q:"Apa yang dikatakan Al-Qur'an tentang akhlak Nabi ﷺ?",c:["Beliau berbudi pekerti yang agung","Beliau keras","Beliau acuh tak acuh","Al-Qur'an tidak membicarakannya"],b:0,e:"“Dan sesungguhnya engkau benar-benar berbudi pekerti yang agung.”",s:['q:68:4']},
  {q:"Dari suku apa Nabi ﷺ berasal?",c:["Quraisy","Aus","Khazraj","Tsaqif"],b:0,e:"Quraisy, suku besar di Mekah.",s:['f:sira']}
 ]},
'pr-livres':{titre:"Kitab-kitab yang diturunkan dan iman",
 texte:["Allah menurunkan kitab-kitab kepada sebagian nabi: Taurat kepada Musa, Zabur kepada Daud, Injil kepada Isa, dan Al-Qur'an kepada Muhammad ﷺ.",
  "Al-Qur'an menyebut nama 25 nabi, tetapi Allah mengutus jauh lebih banyak lagi. Orang beriman mengimani semuanya, tanpa membeda-bedakan.",
  "Iman bertumpu pada enam rukun: beriman kepada Allah, kepada malaikat-malaikat-Nya, kitab-kitab-Nya, rasul-rasul-Nya, hari akhir, dan takdir."],
 retenir:"Taurat, Zabur, Injil, Al-Qur'an. Enam rukun iman.",
 sources:['q:5:44','q:2:285','h:jibril'],
 quiz:[
  {q:"Kitab apa yang Allah turunkan kepada Nabi Musa?",c:["Taurat","Zabur","Injil","Al-Qur'an"],b:0,e:"Taurat kepada Musa, Zabur kepada Daud, Injil kepada Isa, Al-Qur'an kepada Muhammad ﷺ.",s:['q:5:44']},
  {q:"Berapa nabi yang disebut namanya dalam Al-Qur'an?",c:["25","12","40","313"],b:0,e:"25 nabi disebut namanya; 18 di antaranya disebut bersama-sama dalam surah Al-An'am.",s:['f:prophetes25']},
  {q:"Nabi siapa yang disebut Al-Qur'an sebagai “penutup para nabi”, yakni nabi terakhir?",c:["Muhammad ﷺ","Isa","Musa","Ibrahim"],b:0,e:"Muhammad ﷺ adalah nabi yang terakhir.",s:['q:33:40']},
  {q:"Kitab apa yang diturunkan kepada Nabi Daud?",c:["Zabur","Taurat","Injil","Suhuf (lembaran-lembaran) Ibrahim"],b:0,e:"“Dan Kami berikan Kitab Zabur kepada Daud.”",s:['q:4:163']},
  {q:"Apakah beriman kepada kitab-kitab yang diturunkan termasuk bagian dari iman seorang muslim?",c:["Ya, itu termasuk rukun iman","Tidak, hanya kepada Al-Qur'an","Tidak, itu tidak wajib","Hanya selama Ramadan"],b:0,e:"Orang-orang beriman beriman kepada Allah, malaikat-malaikat-Nya, kitab-kitab-Nya, dan rasul-rasul-Nya.",s:['q:2:285']},
  {q:"Berapa jumlah rukun iman?",c:["6","5","4","10"],b:0,e:"Allah, malaikat, kitab, rasul, hari akhir, dan takdir.",s:['h:jibril']},
  {q:"Manakah di antara berikut yang BUKAN rukun iman?",c:["Puasa Ramadan","Beriman kepada malaikat","Beriman kepada hari akhir","Beriman kepada kitab-kitab"],b:0,e:"Puasa adalah rukun Islam (amalan), bukan rukun iman (keyakinan).",s:['h:jibril']},
  {q:"Kitab apa yang Allah jamin pemeliharaannya?",c:["Al-Qur'an","Taurat","Zabur","Semua kitab para raja"],b:0,e:"“Dan sesungguhnya Kami benar-benar memeliharanya.”",s:['q:15:9']},
  {q:"Apakah Al-Qur'an menceritakan kisah semua rasul yang diutus Allah?",c:["Tidak, hanya sebagian","Ya, semuanya","Tidak menceritakan satu pun","Hanya rasul-rasul dari bangsa Arab"],b:0,e:"“Ada beberapa rasul yang telah Kami kisahkan kepadamu, dan ada beberapa rasul yang tidak Kami kisahkan kepadamu.”",s:['q:4:164']},
  {q:"Menurut Al-Qur'an, apakah orang-orang beriman membeda-bedakan para rasul dalam keimanan mereka?",c:["Tidak, mereka beriman kepada semuanya","Ya, mereka hanya beriman kepada satu rasul","Ya, mereka menolak rasul-rasul terdahulu","Mereka tidak beriman kepada satu pun"],b:0,e:"“Kami tidak membeda-bedakan seorang pun dari rasul-rasul-Nya.”",s:['q:2:285']}
 ]},

/* ===================== SEJARAH & SAHABAT ===================== */
'h-khadija':{titre:"Khadijah dan awal mula Islam",
 texte:["Khadijah adalah seorang pedagang yang dihormati di Mekah. Ia menikah dengan Nabi ﷺ, yang saat itu berusia 25 tahun.",
  "Setelah wahyu pertama, dialah yang menenangkan beliau dan menjadi orang pertama yang beriman kepadanya. Ia membawa beliau menemui sepupunya, Waraqah bin Naufal.",
  "Di antara orang-orang pertama yang masuk Islam adalah Abu Bakar, Ali, Zaid bin Haritsah, dan Bilal. Selama 13 tahun di Mekah, umat Islam dianiaya; Sumayyah adalah syahidah pertama."],
 retenir:"Khadijah, orang pertama yang beriman. 13 tahun dakwah di Mekah.",
 sources:['h:hira','f:debuts'],
 quiz:[
  {q:"Siapa istri pertama Nabi ﷺ?",c:["Khadijah","Aisyah","Hafshah","Zainab"],b:0,e:"Khadijah adalah orang pertama yang beriman kepada risalah beliau.",s:['h:hira']},
  {q:"Siapa yang menenangkan Nabi ﷺ tepat setelah wahyu pertama di Gua Hira?",c:["Khadijah","Abu Bakar","Ali","Bilal"],b:0,e:"Beliau pulang kepada Khadijah, yang menenangkannya.",s:['h:hira']},
  {q:"Apa pekerjaan Khadijah di Mekah?",c:["Berdagang","Pengobatan","Bersyair","Beternak unta"],b:0,e:"Ia adalah seorang pedagang kaya yang dihormati.",s:['f:debuts']},
  {q:"Berapa usia Nabi ﷺ ketika menikah dengan Khadijah?",c:["25 tahun","40 tahun","18 tahun","30 tahun"],b:0,e:"Beliau berusia 25 tahun.",s:['f:debuts']},
  {q:"Kepada siapa Khadijah membawa Nabi ﷺ setelah wahyu pertama?",c:["Sepupunya, Waraqah bin Naufal","Abu Thalib","Abu Bakar","Raja Habasyah"],b:0,e:"Waraqah mengenal kitab-kitab suci terdahulu.",s:['h:hira']},
  {q:"Anak laki-laki mana yang termasuk orang-orang pertama yang memeluk Islam?",c:["Ali bin Abi Thalib","Umar","Khalid","Muawiyah"],b:0,e:"Ali, sepupu Nabi ﷺ, saat itu masih kanak-kanak.",s:['f:debuts']},
  {q:"Kira-kira berapa tahun Nabi ﷺ berdakwah di Mekah sebelum Hijrah?",c:["13 tahun","3 tahun","23 tahun","40 tahun"],b:0,e:"Ibnu Abbas meriwayatkan bahwa beliau tinggal 13 tahun di Mekah setelah menerima wahyu.",s:['h:vie']},
  {q:"Sahabat Nabi ﷺ manakah yang menjadi laki-laki dewasa pertama yang memeluk Islam?",c:["Abu Bakar","Umar","Utsman","Hamzah"],b:0,e:"Abu Bakar beriman kepada beliau tanpa ragu.",s:['f:debuts']},
  {q:"Mantan budak mana yang dianiaya karena imannya, lalu menjadi muazin pertama dalam Islam?",c:["Bilal bin Rabah","Zaid bin Haritsah","Salman","Anas"],b:0,e:"Suaranya terdengar jauh: Nabi ﷺ mempercayakan azan kepadanya.",s:['h:adhan']},
  {q:"Siapa nama syahidah pertama dalam Islam?",c:["Sumayyah","Khadijah","Fatimah","Asma"],b:0,e:"Sumayyah, ibu Ammar, dibunuh karena imannya di Mekah.",s:['f:debuts']}
 ]},
'h-hegire':{titre:"Hijrah",
 texte:["Pada tahun 622, karena penganiayaan, Nabi ﷺ meninggalkan Mekah menuju Madinah, yang saat itu bernama Yatsrib: inilah Hijrah. Peristiwa ini menandai tahun 1 kalender Islam.",
  "Selama perjalanan, beliau bersembunyi di Gua Tsur bersama sahabatnya, Abu Bakar.",
  "Di Madinah, beliau disambut oleh kaum Anshar (“para Penolong”), yang berbagi harta mereka dengan kaum Muhajirin (“para Pendatang”). Di sana beliau membangun masjidnya."],
 retenir:"622: Hijrah, tahun 1. Muhajirin dan Anshar.",
 sources:['q:9:40','f:hegire'],
 quiz:[
  {q:"Apa itu Hijrah?",c:["Perpindahan Nabi ﷺ dari Mekah ke Madinah","Haji yang pertama","Sebuah pertempuran","Kelahiran Nabi ﷺ"],b:0,e:"Hijrah menandai tahun 1 kalender Islam.",s:['f:hegire']},
  {q:"Sahabat siapa yang menemani Nabi ﷺ di dalam gua selama Hijrah?",c:["Abu Bakar Ash-Shiddiq","Umar bin Khattab","Ali bin Abi Thalib","Bilal"],b:0,e:"Abu Bakar adalah “salah seorang dari dua orang” di dalam gua.",s:['q:9:40']},
  {q:"Pada tahun berapa Hijrah terjadi?",c:["622","570","632","610"],b:0,e:"Hijrah terjadi pada tahun 622 Masehi.",s:['f:hegire']},
  {q:"Di gua mana Nabi ﷺ bersembunyi selama Hijrah?",c:["Gua Tsur","Gua Hira","Gua Uhud","Gua Badar"],b:0,e:"Tsur berada di selatan Mekah; Hira, tempat wahyu pertama, berada di utara.",s:['f:hegire']},
  {q:"Apa nama lama kota Madinah?",c:["Yatsrib","Bakkah","Taif","Quba"],b:0,e:"Al-Qur'an menyebut nama ini: “Wahai penduduk Yatsrib”.",s:['q:33:13']},
  {q:"Apa sebutan untuk penduduk Madinah yang menyambut kaum muslimin?",c:["Kaum Anshar","Kaum Muhajirin","Kaum Quraisy","Bani Israil"],b:0,e:"Anshar berarti “para Penolong”.",s:['q:9:100']},
  {q:"Apa sebutan untuk kaum muslimin yang berhijrah dari Mekah ke Madinah?",c:["Kaum Muhajirin","Kaum Anshar","Kaum Khawarij","Orang-orang Badui"],b:0,e:"Muhajirin berarti “orang-orang yang berhijrah”.",s:['q:9:100']},
  {q:"Menurut Al-Qur'an, apa yang dikatakan Nabi ﷺ kepada Abu Bakar di dalam gua?",c:["“Jangan bersedih, sesungguhnya Allah bersama kita”","“Ayo cepat lari”","“Mari kembali ke Mekah”","“Mari kita lawan mereka”"],b:0,e:"Inilah ayat 40 surah At-Taubah.",s:['q:9:40']},
  {q:"Pada masa khalifah siapa kalender Hijriah ditetapkan?",c:["Umar","Abu Bakar","Utsman","Ali"],b:0,e:"Umar menjadikan Hijrah sebagai titik awal kalender.",s:['f:hegire']},
  {q:"Apa yang dibangun Nabi ﷺ ketika tiba di Madinah?",c:["Masjidnya","Sebuah istana","Sebuah benteng","Sebuah pasar"],b:0,e:"Masjid Nabi (Masjid Nabawi).",s:['f:hegire']}
 ]},
'h-badr':{titre:"Perang Badar",
 texte:["Pada 17 Ramadan tahun ke-2 Hijriah (624), kaum muslimin menghadapi pasukan Quraisy di dekat sumur-sumur Badar.",
  "Mereka berjumlah sekitar 313 orang, menghadapi hampir 1.000 prajurit. Allah menolong mereka dengan para malaikat, dan mereka meraih kemenangan.",
  "Al-Qur'an menyebut hari itu “hari Furqan” (yaum al-furqân), hari ketika kebenaran dibedakan dari kebatilan."],
 retenir:"17 Ramadan tahun ke-2: Badar, 313 melawan 1.000, hari Furqan.",
 sources:['q:3:123','q:8:9','q:8:41'],
 quiz:[
  {q:"Pada bulan apa Perang Badar terjadi?",c:["Ramadan","Muharram","Zulhijah","Rajab"],b:0,e:"Pada 17 Ramadan tahun ke-2 Hijriah.",s:['f:badr']},
  {q:"Pada tahun Hijriah ke berapa Perang Badar terjadi?",c:["Tahun ke-2","Tahun ke-8","Tahun ke-10","Tahun ke-1"],b:0,e:"Pada tahun 624 Masehi.",s:['f:badr']},
  {q:"Kira-kira berapa jumlah kaum muslimin yang berperang di Badar?",c:["Sekitar 313","Sekitar 3.000","Sekitar 10.000","Sekitar 50"],b:0,e:"Mereka berjumlah sekitar 313 orang.",s:['f:badr']},
  {q:"Kira-kira berapa jumlah prajurit pasukan Quraisy di Badar?",c:["Hampir 1.000","Hampir 100","Hampir 10.000","Hampir 300"],b:0,e:"Penduduk Mekah tiga kali lebih banyak.",s:['f:badr']},
  {q:"Menurut Al-Qur'an, bagaimana Allah menolong kaum muslimin di Badar?",c:["Dengan para malaikat","Dengan badai pasir","Dengan bala bantuan dari Persia","Hanya dengan hujan"],b:0,e:"Allah mengabulkan permohonan mereka dengan mengirim para malaikat.",s:['q:8:9']},
  {q:"Menurut surah Al-Anfal, berapa malaikat yang Allah janjikan sebagai bala bantuan di Badar?",c:["Seribu","Seratus","Sepuluh","Tiga ratus"],b:0,e:"“Sungguh, Aku akan mendatangkan bala bantuan kepadamu dengan seribu malaikat yang datang berturut-turut.”",s:['q:8:9']},
  {q:"Al-Qur'an menyebut hari Badar sebagai apa?",c:["Hari Furqan (yaum al-furqân)","Hari Kebangkitan","Hari raya Id","Hari Hijrah"],b:0,e:"Hari ketika kebenaran dibedakan dari kebatilan.",s:['q:8:41']},
  {q:"Melawan suku apa kaum muslimin berperang di Badar?",c:["Quraisy","Bangsa Romawi","Bangsa Persia","Kaum Anshar"],b:0,e:"Pasukan Quraisy datang dari Mekah.",s:['f:badr']},
  {q:"Pada tanggal berapa di bulan Ramadan Perang Badar terjadi?",c:["Tanggal 17","Tanggal 27","Tanggal 1","Tanggal 10"],b:0,e:"Pada 17 Ramadan tahun ke-2.",s:['f:badr']},
  {q:"Menurut Al-Qur'an, dalam keadaan bagaimana kaum muslimin di Badar?",c:["Mereka dalam keadaan lemah","Mereka sangat banyak","Mereka kaya","Mereka berkuda"],b:0,e:"“Dan sungguh, Allah telah menolong kamu dalam Perang Badar, padahal kamu dalam keadaan lemah.”",s:['q:3:123']}
 ]},
'h-fath':{titre:"Penaklukan Mekah (Fathu Makkah)",
 texte:["Pada tahun ke-8 Hijriah (630), di bulan Ramadan, Nabi ﷺ memasuki Mekah bersama sekitar 10.000 muslim, hampir tanpa pertempuran.",
  "Beliau memaafkan musuh-musuh lamanya dan membersihkan Kakbah dari 360 berhala, sambil membaca: “Kebenaran telah datang dan kebatilan telah lenyap.”",
  "Surah An-Nasr mengabarkan pertolongan Allah ini dan masuknya manusia ke dalam Islam secara berbondong-bondong."],
 retenir:"Ramadan tahun ke-8: Mekah dibuka, berhala dihancurkan, maaf diberikan.",
 sources:['q:17:81','h:idoles','q:110:1'],
 quiz:[
  {q:"Pada tahun Hijriah ke berapa Mekah ditaklukkan?",c:["Tahun ke-8","Tahun ke-2","Tahun ke-1","Tahun ke-11"],b:0,e:"Pada tahun 630 Masehi.",s:['f:fath']},
  {q:"Pada bulan apa penaklukan Mekah terjadi?",c:["Ramadan","Syawal","Zulhijah","Muharram"],b:0,e:"Penaklukan Mekah terjadi pada bulan Ramadan.",s:['f:fath']},
  {q:"Kira-kira berapa muslim yang menyertai Nabi ﷺ saat penaklukan Mekah?",c:["Sekitar 10.000","Sekitar 313","Sekitar 1.000","Sekitar 100"],b:0,e:"Pasukan yang berjumlah sekitar 10.000 orang.",s:['f:fath']},
  {q:"Berapa berhala yang mengelilingi Kakbah pada hari penaklukan Mekah?",c:["360","12","99","1.000"],b:0,e:"Abdullah bin Mas'ud meriwayatkan bahwa jumlahnya 360.",s:['h:idoles']},
  {q:"Ayat apa yang dibaca Nabi ﷺ ketika merobohkan berhala-berhala di Kakbah?",c:["“Kebenaran telah datang dan kebatilan telah lenyap”","“Dengan nama Allah”","“Katakanlah: Dialah Allah, Yang Maha Esa”","“Bacalah!”"],b:0,e:"Inilah ayat 81 surah Al-Isra.",s:['q:17:81','h:idoles']},
  {q:"Bagaimana Nabi ﷺ memperlakukan musuh-musuh lamanya dari Mekah setelah penaklukan?",c:["Beliau memaafkan mereka","Beliau mengusir mereka","Beliau memenjarakan mereka","Beliau mengasingkan mereka ke Habasyah"],b:0,e:"Beliau memberikan pengampunan umum kepada penduduk Mekah.",s:['f:fath']},
  {q:"Surah apa yang mengabarkan “pertolongan Allah dan kemenangan”?",c:["An-Nasr (110)","Al-Fath (48)","Al-Fil (105)","Al-Kautsar (108)"],b:0,e:"“Apabila telah datang pertolongan Allah dan kemenangan.”",s:['q:110:1']},
  {q:"Menurut surah An-Nasr, bagaimana manusia masuk ke dalam Islam?",c:["Berbondong-bondong","Satu per satu, secara diam-diam","Dengan paksaan","Tidak ada yang masuk"],b:0,e:"“Dan engkau melihat manusia berbondong-bondong masuk agama Allah.”",s:['q:110:2']},
  {q:"Apakah penaklukan Mekah terjadi melalui pertempuran besar?",c:["Tidak, hampir tanpa pertempuran","Ya, pertempuran terbesar dalam sejarah","Ya, selama setahun","Ya, di kaki Gunung Uhud"],b:0,e:"Kota itu dibuka secara damai, hampir tanpa bentrokan.",s:['f:fath']},
  {q:"Apa yang diperintahkan surah An-Nasr setelah kemenangan?",c:["Bertasbih memuji Allah dan memohon ampunan kepada-Nya","Segera berhaji","Berpuasa tiga hari","Membangun kembali Kakbah"],b:0,e:"“Maka bertasbihlah dengan memuji Tuhanmu dan mohonlah ampunan kepada-Nya.”",s:['q:110:3']}
 ]},
'h-califes':{titre:"Empat khalifah pertama",
 texte:["Setelah Nabi ﷺ wafat pada tahun 632, empat khalifah memimpin secara berturut-turut: Abu Bakar, Umar, Utsman, dan Ali. Mereka disebut “Khulafaur Rasyidin” (para khalifah yang mendapat petunjuk).",
  "Abu Bakar memerintahkan Zaid bin Tsabit untuk mengumpulkan Al-Qur'an dalam satu mushaf. Pada masa Umar, Islam meluas dan kalender Hijriah ditetapkan.",
  "Utsman memerintahkan agar Al-Qur'an disalin menjadi beberapa mushaf yang dikirim ke berbagai wilayah. Ali, sepupu sekaligus menantu Nabi ﷺ, adalah khalifah keempat."],
 retenir:"Abu Bakar, Umar, Utsman, Ali: empat Khulafaur Rasyidin.",
 sources:['h:compilation','h:copies','f:califes'],
 quiz:[
  {q:"Siapa khalifah pertama setelah Nabi ﷺ wafat?",c:["Abu Bakar","Umar","Ali","Utsman"],b:0,e:"Abu Bakar, lalu Umar, Utsman, dan Ali.",s:['f:califes']},
  {q:"Berapa jumlah “Khulafaur Rasyidin” yang menggantikan Nabi ﷺ?",c:["4","3","5","12"],b:0,e:"Mereka disebut al-khulafâ' ar-râsyidûn.",s:['f:califes']},
  {q:"Bagaimana urutan empat khalifah pertama?",c:["Abu Bakar, Umar, Utsman, Ali","Ali, Umar, Abu Bakar, Utsman","Umar, Abu Bakar, Ali, Utsman","Utsman, Ali, Umar, Abu Bakar"],b:0,e:"Dari tahun 632 sampai 661.",s:['f:califes']},
  {q:"Pada masa khalifah siapa Al-Qur'an pertama kali dikumpulkan dalam satu mushaf?",c:["Abu Bakar","Umar","Utsman","Ali"],b:0,e:"Setelah Perang Yamamah, ketika banyak penghafal Al-Qur'an gugur.",s:['h:compilation']},
  {q:"Sahabat siapa yang ditugaskan mengumpulkan Al-Qur'an pada masa Abu Bakar?",c:["Zaid bin Tsabit","Bilal","Khalid bin Walid","Salman"],b:0,e:"Zaid bin Tsabit dahulu adalah penulis wahyu.",s:['h:compilation']},
  {q:"Khalifah mana yang memerintahkan agar Al-Qur'an disalin menjadi beberapa mushaf yang dikirim ke berbagai wilayah?",c:["Utsman","Abu Bakar","Umar","Ali"],b:0,e:"Untuk menyatukan bacaan di seluruh dunia Islam.",s:['h:copies']},
  {q:"Apa hubungan kekerabatan antara Ali dan Nabi ﷺ?",c:["Sepupu sekaligus menantunya","Saudaranya","Pamannya","Kakeknya"],b:0,e:"Ali adalah suami Fatimah, putri Nabi ﷺ.",s:['f:califes']},
  {q:"Khalifah mana yang dijuluki “Al-Faruq”, yang membedakan antara yang benar dan yang salah?",c:["Umar","Abu Bakar","Utsman","Ali"],b:0,e:"Umar bin Khattab.",s:['f:califes']},
  {q:"Khalifah mana yang dijuluki “Ash-Shiddiq”, yang membenarkan?",c:["Abu Bakar","Umar","Utsman","Ali"],b:0,e:"Abu Bakar langsung membenarkan semua yang disampaikan Nabi ﷺ.",s:['f:califes']},
  {q:"Khalifah mana yang menikahi dua putri Nabi ﷺ secara berturut-turut?",c:["Utsman","Umar","Abu Bakar","Ali"],b:0,e:"Karena itulah ia dijuluki “Dzun Nurain”, pemilik dua cahaya.",s:['f:califes']}
 ]}
},

/* Catatan (sumber sejarah atau praktik, tanpa teks Arab) */
faits:{
 mois:{titre:"Catatan",texte:"12 bulan Hijriah: Muharram, Safar, Rabiulawal, Rabiulakhir, Jumadilawal, Jumadilakhir, Rajab, Syakban, Ramadan, Syawal, Zulkaidah, Zulhijah."},
 jeune2:{titre:"Catatan sejarah",texte:"Puasa Ramadan diwajibkan di Madinah, pada tahun ke-2 Hijriah (624)."},
 conditions:{titre:"Catatan",texte:"Para ulama menetapkan syarat wajib puasa: beragama Islam, balig, berakal sehat, dan mampu berpuasa."},
 aid:{titre:"Catatan",texte:"Islam memiliki dua hari raya: Idulfitri, pada 1 Syawal, di akhir Ramadan, dan Iduladha, pada 10 Zulhijah, pada musim haji."},
 shahada:{titre:"Catatan",texte:"Lafal syahadat: “Ash-hadu an lâ ilâha illâ Llâh, wa ash-hadu anna Muḥammadan rasûlu Llâh” — “Aku bersaksi bahwa tiada tuhan selain Allah, dan aku bersaksi bahwa Muhammad adalah utusan Allah”."},
 rakat:{titre:"Praktik yang diwariskan",texte:"Jumlah rakaat setiap salat berasal dari praktik Nabi ﷺ, yang diwariskan oleh seluruh umat Islam: Subuh 2, Zuhur 4, Asar 4, Magrib 3, Isya 4, yaitu 17 rakaat sehari."},
 zakat:{titre:"Catatan",texte:"Zakat uang adalah 2,5% (seperempat puluh) dari tabungan yang mencapai nisab dan dimiliki selama satu tahun lunar (haul). Sedekah adalah pemberian sukarela. Untuk kasus-kasus khusus, tanyakanlah kepada seorang ulama."},
 hajj:{titre:"Catatan",texte:"Haji berlangsung dari tanggal 8 sampai 13 Zulhijah. Jemaah memasuki ihram (laki-laki mengenakan dua helai kain putih tidak berjahit), melakukan tawaf (tujuh putaran mengelilingi Kakbah) dan sai (tujuh kali perjalanan antara Safa dan Marwah). Tanggal 9 adalah hari Arafah, tanggal 10 Iduladha."},
 coran:{titre:"Catatan",texte:"Al-Qur'an terdiri dari 114 surah dan 6.236 ayat menurut hitungan yang paling umum. Al-Qur'an dibagi menjadi 30 bagian (juz). Satu ayat disebut âyah. Surah yang diwahyukan sebelum Hijrah disebut Makkiyah, yang sesudahnya Madaniyah. Yang terpanjang adalah Al-Baqarah (286 ayat)."},
 tawba:{titre:"Catatan",texte:"Surah At-Taubah (9) adalah satu-satunya dari 114 surah yang tidak diawali dengan “Bismi Llâhi r-Raḥmâni r-Raḥîm”."},
 ikhlas:{titre:"Catatan",texte:"Al-Ikhlas berarti “tauhid yang murni, ketulusan”: surah ini memurnikan iman dari segala bentuk syirik."},
 hawwa:{titre:"Catatan",texte:"Al-Qur'an menyebut istri Adam tanpa menyebut namanya. Namanya, Hawa, berasal dari Sunah dan para ulama."},
 musa:{titre:"Catatan",texte:"Musa adalah nabi yang paling sering disebut namanya dalam Al-Qur'an: lebih dari 130 kali."},
 maryam:{titre:"Catatan",texte:"Maryam adalah satu-satunya perempuan yang disebut namanya dalam Al-Qur'an. Surah ke-19 dinamai dengan namanya."},
 sira:{titre:"Catatan sejarah",texte:"Nabi ﷺ lahir di Mekah sekitar tahun 570, dari suku Quraisy. Ayahnya telah wafat; beliau kehilangan ibunya, Aminah, pada usia 6 tahun, lalu diasuh oleh kakeknya Abdul Muthalib, kemudian oleh pamannya Abu Thalib. Beliau dijuluki Al-Amin. Beliau wafat di Madinah pada tahun 632."},
 prophetes25:{titre:"Catatan",texte:"25 nabi disebut namanya dalam Al-Qur'an. 18 di antaranya disebut bersama-sama dalam surah Al-An'am (6), ayat 83 sampai 86."},
 debuts:{titre:"Catatan sejarah",texte:"Khadijah, seorang pedagang kaya, menikah dengan Nabi ﷺ ketika beliau berusia 25 tahun. Di antara orang-orang yang paling awal masuk Islam: Khadijah, Abu Bakar, Ali (yang masih kanak-kanak), Zaid bin Haritsah. Bilal, budak yang dianiaya lalu dimerdekakan, menjadi muazin pertama. Sumayyah, ibu Ammar, adalah syahidah pertama."},
 hegire:{titre:"Catatan sejarah",texte:"Hijrah terjadi pada tahun 622. Nabi ﷺ dan Abu Bakar bersembunyi di Gua Tsur. Madinah dahulu bernama Yatsrib. Nabi ﷺ membangun masjidnya di sana. Kalender Hijriah ditetapkan pada masa kekhalifahan Umar."},
 badr:{titre:"Catatan sejarah",texte:"Perang Badar terjadi pada 17 Ramadan tahun ke-2 (624). Sekitar 313 muslim menghadapi hampir 1.000 prajurit Quraisy."},
 fath:{titre:"Catatan sejarah",texte:"Mekah dibuka pada bulan Ramadan tahun ke-8 (630), hampir tanpa pertempuran, oleh sekitar 10.000 muslim. Nabi ﷺ memberikan pengampunan umum kepada penduduk Mekah."},
 califes:{titre:"Catatan sejarah",texte:"Empat Khulafaur Rasyidin: Abu Bakar Ash-Shiddiq (632-634), Umar Al-Faruq (634-644), Utsman Dzun Nurain (644-656), yang menikahi dua putri Nabi ﷺ, Ruqayyah lalu Ummu Kultsum, dan Ali (656-661), sepupu Nabi ﷺ dan suami putrinya, Fatimah."}
},

/* Ringkasan yang ditampilkan untuk hadis-hadis panjang (teks lengkapnya tetap dapat diakses) */
resumes:{
 cinq:"Pada peristiwa Isra Mikraj, awalnya diwajibkan lima puluh salat, lalu diringankan hingga menjadi lima salat sehari.",
 enfants:"Ar-Rubayyi' binti Mu'awwidz menceritakan bahwa para sahabat menyuruh anak-anak kecil mereka berpuasa pada hari Asyura, dan memberi mereka mainan dari wol agar mereka sabar menunggu waktu berbuka.",
 hira:"Aisyah menceritakan bahwa Nabi ﷺ biasa menyendiri di Gua Hira. Malaikat datang dan berkata kepadanya: “Bacalah!”. Beliau pulang kepada Khadijah, yang menenangkannya, lalu membawanya menemui sepupunya, Waraqah bin Naufal.",
 regles:"Aisyah menjelaskan bahwa mereka diperintahkan untuk mengganti puasa yang ditinggalkan selama haid, tetapi tidak mengganti salat.",
 tarawih:"Nabi ﷺ salat malam di masjid selama Ramadan; orang-orang salat di belakang beliau, semakin lama semakin banyak. Lalu beliau tidak keluar lagi, karena khawatir salat itu diwajibkan atas mereka.",
 adhan:"Sahabat Abdullah bin Zaid melihat lafal-lafal azan dalam mimpi. Nabi ﷺ membenarkan mimpi itu dan meminta Bilal untuk mengumandangkan azan, karena suaranya lebih lantang.",
 ikhlas:"Seorang laki-laki terus-menerus membaca surah Al-Ikhlas dan menganggapnya sedikit. Nabi ﷺ bersabda: “Surah itu setara dengan sepertiga Al-Qur'an.”",
 kursi:"Nabi ﷺ bertanya kepada Ubay bin Ka'ab tentang ayat yang paling agung dalam Kitab Allah. Ia menjawab: Ayat Kursi. Nabi ﷺ memujinya atas ilmunya.",
 hajj_une:"Nabi ﷺ mengumumkan bahwa haji telah diwajibkan. Seorang laki-laki bertanya: “Setiap tahun?” Beliau menjawab bahwa jika beliau berkata ya, niscaya haji menjadi wajib setiap tahun: haji wajib sekali saja.",
 arafa:"Beberapa orang bertanya kepada Nabi ﷺ di Arafah tentang haji. Beliau menjawab: “Haji itu adalah Arafah.”",
 jibril:"Malaikat Jibril, dalam rupa manusia, bertanya kepada Nabi ﷺ tentang Islam, iman, dan ihsan. Iman: beriman kepada Allah, malaikat-malaikat-Nya, kitab-kitab-Nya, rasul-rasul-Nya, hari akhir, dan takdir, yang baik maupun yang buruk.",
 vie:"Ibnu Abbas meriwayatkan bahwa Nabi ﷺ menerima wahyu pada usia 40 tahun, tinggal 13 tahun di Mekah, berhijrah ke Madinah dan tinggal di sana 10 tahun, lalu wafat pada usia 63 tahun.",
 idoles:"Pada hari penaklukan, ada 360 berhala di sekeliling Kakbah. Nabi ﷺ memukulnya dengan tongkat sambil membaca: “Kebenaran telah datang dan kebatilan telah lenyap.”",
 compilation:"Setelah Perang Yamamah, ketika banyak penghafal Al-Qur'an gugur, Abu Bakar menugaskan Zaid bin Tsabit untuk mengumpulkan Al-Qur'an dalam satu mushaf.",
 copies:"Utsman, yang khawatir akan perbedaan bacaan di antara berbagai wilayah, memerintahkan agar mushaf Al-Qur'an disalin menjadi beberapa salinan yang dikirim ke setiap wilayah.",
 fitr_but:"Ibnu Abbas meriwayatkan bahwa Nabi ﷺ mewajibkan zakat fitrah untuk menyucikan orang yang berpuasa dari perkataan sia-sia dan kotor, serta untuk memberi makan orang-orang miskin.",
 afw:"Aisyah bertanya apa yang harus ia ucapkan jika ia mengetahui Malam Kemuliaan. Beliau menjawab: “Ucapkanlah: Allâhumma innaka ʿafuwwun tuḥibbu l-ʿafwa faʿfu ʿannî” — Ya Allah, Engkau Maha Pemaaf, Engkau menyukai pemaafan, maka maafkanlah aku."
}
};
